window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch01"]={"id": "ch01", "title": "第一章 绪论", "sub": "朱玉贤《现代分子生物学》第5版 · 教师课件逐页详解", "sub2": "分子生物学发展史 · 里程碑 · 研究方法", "modules": [{"i": 0, "name": "模块一：分子生物学与21世纪生命科学", "slides": [{"i": 0, "sec": "模块一：分子生物学与21世纪生命科学", "title": "分子生物学发展的重要里程碑(p2)", "notes": "本页以时间轴形式梳理了分子生物学及生命科学的关键节点：1859年达尔文《物种起源》奠定进化论基础；1865年孟德尔《植物杂交实验》揭示遗传规律；1910年摩尔根果蝇杂交实验将基因定位到染色体；1953年沃森和克里克提出DNA双螺旋结构，标志现代分子生物学诞生；2000年人类基因组工作草图宣布完成，开启基因组学时代；此后CRISPR-Cas9可编程基因编辑技术建立，使精准修改基因成为可能。这些里程碑体现了生命科学从描述到机制、从读到写的飞跃。", "page": 2, "level": "掌握", "img": "assets/img/ch01/p002.jpg", "anim": null, "fig": "本页为时间轴示意图，横轴表示时间，节点标注各里程碑年份与事件。看图时按时间顺序从左到右，重点记住1953年DNA双螺旋（学科诞生标志）和2000年人类基因组计划两个关键节点。", "points": ["1859年达尔文《物种起源》奠定进化论基础", "1865年孟德尔《植物杂交实验》揭示遗传规律", "1910年摩尔根果蝇实验将基因定位到染色体", "1953年沃森和克里克提出DNA双螺旋结构，标志现代分子生物学诞生", "2000年人类基因组工作草图完成，开启基因组学时代；CRISPR-Cas9使精准基因编辑成为可能"], "check": null, "cards": [{"front": "现代分子生物学诞生的标志是什么？", "back": "1953年沃森和克里克提出DNA双螺旋结构。", "mnemonic": "沃克双螺旋，分子生物学元年。", "useImg": false}, {"front": "社会各界如何关注生命科学？", "back": "政府关注前沿、科学家抢占制高点、企业家投资生物技术、媒体聚焦成果、民众关心转基因与环境安全、高校将分子生物学列为学位课程。", "mnemonic": "政科企媒民校，六方共关注。", "useImg": false}]}, {"i": 1, "sec": "模块一：分子生物学与21世纪生命科学", "title": "21世纪是生命科学的世纪(p3)", "notes": "本页用数据说明生命科学的学科地位：当今学术论文中生命科学类占53%，在《Nature》《Science》等权威刊物中更高达56%。这组数据直观表明生命科学已成为当代科学研究的主流和重心。分子生物学作为生命科学的核心与前沿，带动了医学、农业、环境、生物技术等领域的快速发展。因此，21世纪被称为生命科学的世纪，学习分子生物学有助于理解现代生命科学的基本框架和发展方向。", "page": 3, "level": "理解", "img": "assets/img/ch01/p003.jpg", "anim": null, "fig": null, "points": ["生命科学类论文占当今学术论文的53%", "在《Nature》《Science》等权威刊物中生命科学类占56%", "生命科学已成为当代科学研究的主流和重心", "分子生物学是生命科学的核心与前沿，带动医学、农业、环境、生物技术等领域发展", "21世纪被称为生命科学的世纪"], "check": null, "cards": [{"front": "分子生物学发展中的关键里程碑有哪些？", "back": "1859达尔文《物种起源》；1865孟德尔遗传规律；1910摩尔根基因定位染色体；1953 DNA双螺旋；2000人类基因组草图；此后CRISPR-Cas9基因编辑。", "mnemonic": "达孟摩沃人CR，六步走完分子史。", "useImg": false}]}, {"i": 2, "sec": "模块一：分子生物学与21世纪生命科学", "title": "社会各界高度关注生命科学(p4)", "notes": "本页从政府、科学家、企业、媒体、民众和高校六个层面说明生命科学受到的广泛关注：各国政府高度关注前沿学科，科学家联合抢占制高点，有远见的企业家投入巨资发展生物技术，新闻媒体频繁聚焦生物技术成果，民众关心转基因食品与环境安全，高校将分子生物学列为学位课程。以DNA双螺旋和中心法则为核心的现代分子生物学，正引发事件、决策和观念的更新，标志着生命科学世纪全面到来。", "page": 4, "level": "了解", "img": "assets/img/ch01/p004.jpg", "anim": null, "fig": null, "points": ["政府高度关注前沿学科，科学家联合抢占制高点", "有远见的企业家投入巨资发展生物技术", "新闻媒体频繁聚焦生物技术成果，民众关心转基因食品与环境安全", "高校将分子生物学列为学位课程", "以DNA双螺旋和中心法则为核心的现代分子生物学正引发事件、决策和观念的更新"], "check": null, "cards": [{"front": "为什么说21世纪是生命科学的世纪？", "back": "生命科学论文占53%，在《Nature》《Science》中达56%，已成为科研主流；分子生物学作为核心带动医学、农业、环境、生物技术发展。", "mnemonic": "论文过半，生命当先。", "useImg": false}]}], "mcq": [{"id": "ch01_mcq_1", "mod": "模块一：分子生物学与21世纪生命科学", "modI": 0, "q": "标志着现代分子生物学诞生的里程碑事件是（　）。", "o": ["A. 1859年《物种起源》发表", "B. 1865年《植物杂交实验》发表", "C. 1953年DNA双螺旋结构模型提出", "D. 2000年人类基因组工作草图完成"], "a": "C", "e": "1953年沃森和克里克提出DNA双螺旋结构模型，并随后促成中心法则的建立，被视为现代分子生物学诞生的标志。A、B是遗传学与进化论的重要基础，D是基因组学时代的里程碑。", "kp": "ch01_s0_0"}, {"id": "ch01_mcq_2", "mod": "模块一：分子生物学与21世纪生命科学", "modI": 0, "q": "根据PPT数据，在《Nature》《Science》等权威刊物中，生命科学类论文所占比例约为（　）。", "o": ["A. 35%", "B. 45%", "C. 53%", "D. 56%"], "a": "D", "e": "PPT指出，当今学术论文中生命科学类占53%，而在《Nature》《Science》等权威刊物中达到56%。因此选D。", "kp": "ch01_s0_1"}, {"id": "ch01_mcq_3", "mod": "模块一：分子生物学与21世纪生命科学", "modI": 0, "q": "下列哪项技术被称为可编程基因编辑技术，并在人类基因组工作草图完成之后建立？（　）", "o": ["A. PCR技术", "B. CRISPR-Cas9", "C. 桑格测序法", "D. 基因重组技术"], "a": "B", "e": "CRISPR-Cas9是一种可编程的基因编辑技术，能够对基因组进行精准修饰，是继人类基因组计划之后分子生物学领域的重大突破。PCR、桑格测序和基因重组技术均早于或不属于可编程基因编辑范畴。", "kp": "ch01_s0_0"}, {"id": "ch01_mcq_4", "mod": "模块一：分子生物学与21世纪生命科学", "modI": 0, "q": "PPT从多个层面说明生命科学受到高度关注，下列哪项不属于其列举的层面？（　）", "o": ["A. 各国政府高度关注生命科学前沿学科", "B. 企业家投巨资发展生物技术", "C. 新闻媒体聚焦生物技术成果", "D. 各国政府限制分子生物学课程设置"], "a": "D", "e": "PPT列举的层面包括政府关注、科学家抢占制高点、企业家投资、媒体聚焦、民众关心以及高校将分子生物学列为学位课程。D项“限制分子生物学课程设置”与原文相反，不属于列举内容。", "kp": "ch01_s0_2"}, {"id": "ch01_mcq_5", "mod": "模块一：分子生物学与21世纪生命科学", "modI": 0, "q": "现代分子生物学的核心理论框架主要包括（　）。", "o": ["A. 细胞学说和进化论", "B. DNA双螺旋结构模型和中心法则", "C. 孟德尔遗传定律和染色体学说", "D. 自然选择学说和基因漂变理论"], "a": "B", "e": "PPT明确指出，以DNA双螺旋结构模型和“中心法则”为核心的现代分子生物学引发了各种事件、决策和观念的更新。因此B项正确。", "kp": "ch01_s0_0"}], "judge": [], "fill": [{"id": "ch01_fill_5", "modI": 0, "q": "2000年，________工作草图宣布完成，开启基因组学时代。", "a": "人类基因组", "kp": "ch01_s0_0"}], "short": [{"id": "ch01_short_1", "modI": 0, "q": "简述分子生物学发展的重要里程碑。", "a": "1. 1859年达尔文《物种起源》奠定进化论基础；2. 1865年孟德尔《植物杂交实验》揭示遗传规律；3. 1910年摩尔根果蝇杂交实验将基因定位到染色体；4. 1953年沃森和克里克提出DNA双螺旋结构，标志现代分子生物学诞生；5. 2000年人类基因组工作草图宣布完成，开启基因组学时代；6. 此后CRISPR-Cas9可编程基因编辑技术建立，使精准修改基因成为可能。", "kps": "", "kp": "ch01_s0_0"}, {"id": "ch01_short_2", "modI": 0, "q": "为什么说21世纪是生命科学的世纪？", "a": "1. 当今学术论文中生命科学类占53%，在《Nature》《Science》等权威刊物中更高达56%；2. 生命科学已成为当代科学研究的主流和重心；3. 分子生物学作为生命科学的核心与前沿，带动医学、农业、环境、生物技术等领域快速发展；4. 学习分子生物学有助于理解现代生命科学的基本框架和发展方向。", "kps": "", "kp": "ch01_s0_1"}], "calc": [], "term": [{"id": "ch01_term_1", "modI": 0, "term": "Molecular Biology", "def": "现代分子生物学：以DNA双螺旋结构和中心法则为核心，从分子层次研究生命现象的科学；1953年沃森和克里克提出DNA双螺旋结构标志其诞生；是生命科学的核心与前沿，带动医学、农业、环境、生物技术等领域发展。", "kps": "", "kp": null}]}, {"i": 1, "name": "模块二：发展历程(一)——进化论与细胞学说", "slides": [{"i": 0, "sec": "发展历程(一)——进化论与细胞学说", "title": "达尔文生平与《物种起源》(p5)", "notes": "本页梳理达尔文的人生轨迹：1809年出生于医生世家，1825—1827年在爱丁堡大学学医，因对自然历史兴趣浓厚而转向；1828—1831年入剑桥大学学神学；1831—1836年随贝格尔号军舰环球考察，积累大量生物与地质证据；1859年发表《物种起源》，1882年病逝。达尔文的经历说明，科学发现既需要长期观察与积累，也离不开跨学科的兴趣与坚持。", "page": 5, "level": "了解", "img": "assets/img/ch01/p005.jpg", "anim": null, "fig": null, "points": ["达尔文1809年出生于医生世家，先后在爱丁堡大学学医、剑桥大学学神学", "1831—1836年随贝格尔号军舰环球考察，积累大量生物与地质证据", "1859年发表《物种起源》，1882年病逝", "其经历说明科学发现需要长期观察积累与跨学科兴趣、坚持"], "check": null, "cards": [{"front": "达尔文是哪一年发表《物种起源》的？", "back": "1859年。", "mnemonic": "1859，物种起源久（九）流传。", "useImg": false}]}, {"i": 1, "sec": "发展历程(一)——进化论与细胞学说", "title": "进化论动摇“创世说”(p6)", "notes": "1859年达尔文出版《物种起源》，提出以自然选择为核心的进化论，用“物竞天择，适者生存”解释物种起源与多样性。该理论从根基上动摇了上帝创造万物的“创世说”，使生物学摆脱神学束缚，走上以自然原因解释生命现象的道路。进化论与细胞学说、孟德尔遗传学共同构成现代生命科学的重要基石，也为分子生物学研究提供历史与思想背景。", "page": 6, "level": "掌握", "img": "assets/img/ch01/p006.jpg", "anim": null, "fig": null, "points": ["1859年达尔文出版《物种起源》，提出以自然选择为核心的进化论", "核心观点：物竞天择，适者生存，用以解释物种起源与多样性", "进化论从根本上动摇了上帝创造万物的创世说，使生物学摆脱神学束缚", "进化论与细胞学说、孟德尔遗传学共同构成现代生命科学的重要基石"], "check": null, "cards": [{"front": "达尔文随哪艘军舰进行了环球考察？考察时间是什么？", "back": "贝格尔号军舰，1831—1836年。", "mnemonic": "贝格尔号，1831出发，1836归。", "useImg": false}]}, {"i": 2, "sec": "发展历程(一)——进化论与细胞学说", "title": "讽刺达尔文的漫画(p7)", "notes": "本页展示当时报纸刊登的讽刺达尔文的漫画，反映进化论问世初期所遭遇的社会争议与宗教阻力。漫画常以人猿关系等形象嘲讽达尔文，说明科学新理论的确立往往需要经历质疑与论争。理解这一背景，有助于认识科学知识的社会性，以及科学精神中实证、批判与坚持的重要性。", "page": 7, "level": "了解", "img": "assets/img/ch01/p007.jpg", "anim": null, "fig": "观察漫画中人物形象与文字标题，注意其如何以夸张、戏谑手法将达尔文与猿类联系起来；由此体会进化论问世初期所面临的社会嘲讽与宗教阻力。", "points": ["本页展示当时报纸刊登的讽刺达尔文的漫画", "漫画常以人猿关系等形象嘲讽达尔文，反映进化论初期遭遇的社会争议与宗教阻力", "说明科学新理论的确立往往需要经历质疑与论争", "有助于认识科学知识的社会性及实证、批判、坚持的科学精神"], "check": null, "cards": [{"front": "进化论的核心观点是什么？它动摇了什么？", "back": "以自然选择为核心，“物竞天择，适者生存”；动摇了上帝创造万物的“创世说”，使生物学摆脱神学束缚。", "mnemonic": "物竞天择，适者生存；进化一出，创世动摇。", "useImg": false}]}, {"i": 3, "sec": "发展历程(一)——进化论与细胞学说", "title": "历史人物排名与达尔文影响(p8)", "notes": "本页引用剑桥大学出版社2013年《谁更伟大？历史人物的真实排名》的研究，列出历史人物总排行前5位：耶稣、拿破仑、默罕默德、莎士比亚、林肯，并给出网站。该材料用于说明对历史人物影响力的量化评价，也提示达尔文虽未列前五，但其进化论对科学、思想与社会的深远影响同样巨大。科学家的贡献常通过改变人类世界观而体现。", "page": 8, "level": "了解", "img": "assets/img/ch01/p008.jpg", "anim": null, "fig": null, "points": ["引用剑桥大学出版社2013年《谁更伟大？历史人物的真实排名》研究", "历史人物总排行前5位：耶稣、拿破仑、默罕默德、莎士比亚、林肯", "该材料用于说明对历史人物影响力的量化评价", "达尔文虽未列前五，但其进化论对科学、思想与社会的深远影响同样巨大", "科学家的贡献常通过改变人类世界观而体现"], "check": null, "cards": [{"front": "现代生命科学的重要基石包括哪三大理论？", "back": "进化论、细胞学说、孟德尔遗传学。", "mnemonic": "进细孟——进击的细胞孟德尔。", "useImg": false}]}, {"i": 4, "sec": "发展历程(一)——进化论与细胞学说", "title": "列文虎克与显微镜观察(p9)", "notes": "列文虎克是荷兰显微镜学家、微生物学开拓者，出身“草根”，凭借浓厚兴趣和精湛磨镜技术，自制单式显微镜并首次观察记录到细菌、原生动物、精子等微小生物。他的实践体现“兴趣驱动、实践出真知”，为细胞学说的建立提供了观察工具与事实基础，也说明技术革新对生物学发展的关键推动作用。", "page": 9, "level": "理解", "img": "assets/img/ch01/p009.jpg", "anim": null, "fig": null, "points": ["列文虎克是荷兰显微镜学家、微生物学开拓者，出身草根", "凭借浓厚兴趣和精湛磨镜技术，自制单式显微镜", "首次观察记录到细菌、原生动物、精子等微小生物", "体现兴趣驱动、实践出真知，为细胞学说建立提供观察工具与事实基础", "说明技术革新对生物学发展具有关键推动作用"], "check": null, "cards": [{"front": "列文虎克的主要贡献是什么？", "back": "荷兰显微镜学家、微生物学开拓者，自制单式显微镜，首次观察记录到细菌、原生动物、精子等微小生物。", "mnemonic": "列文虎克磨镜片，微小生物首露面。", "useImg": false}]}, {"i": 5, "sec": "发展历程(一)——进化论与细胞学说", "title": "胡克与“cell”一词的提出(p10)", "notes": "罗伯特·胡克是英国力学、光学、天文学家，他改进复合显微镜，1665年出版《显微图谱》(Micrographia)。在观察软木薄片时，他看到许多小室，首次将其命名为“cell”（细胞）。虽然胡克看到的主要是植物死细胞的细胞壁，但“cell”一词由此进入生物学，成为细胞学说的核心概念，标志着人类开始从显微层次认识生命结构。", "page": 10, "level": "掌握", "img": "assets/img/ch01/p010.jpg", "anim": null, "fig": null, "points": ["罗伯特·胡克是英国力学、光学、天文学家，改进复合显微镜", "1665年出版《显微图谱》(Micrographia)", "观察软木薄片时看到许多小室，首次命名为cell（细胞）", "胡克看到的主要是植物死细胞的细胞壁，但cell一词由此进入生物学", "cell成为细胞学说的核心概念，标志人类开始从显微层次认识生命结构"], "check": null, "cards": [{"front": "“cell”（细胞）一词是谁提出的？在哪本书中？", "back": "罗伯特·胡克，1665年《显微图谱》(Micrographia)中首次提出。", "mnemonic": "胡克看软木，小室叫cell。", "useImg": false}]}, {"i": 6, "sec": "发展历程(一)——进化论与细胞学说", "title": "细胞学说的建立(p11)", "notes": "1838—1839年，德国植物学家施莱登与动物学家施旺分别研究植物和动物组织，提出：植物和动物都由细胞组成；细胞是生物体结构和功能的基本单位。两人身世不同却志同道合，共同建立细胞学说。该学说与进化论、孟德尔遗传学并称现代生物学三大基石，奠定了细胞学发展的基础，也为分子生物学从细胞层次深入分子层次提供前提。", "page": 11, "level": "掌握", "img": "assets/img/ch01/p011.jpg", "anim": null, "fig": null, "points": ["1838—1839年德国植物学家施莱登与动物学家施旺分别研究植物和动物组织", "提出植物和动物都由细胞组成", "细胞是生物体结构和功能的基本单位", "两人共同建立细胞学说，与进化论、孟德尔遗传学并称现代生物学三大基石", "细胞学说奠定细胞学发展基础，为分子生物学从细胞层次深入分子层次提供前提"], "check": null, "cards": [{"front": "细胞学说是谁建立的？其核心内容是什么？", "back": "1838—1839年由德国植物学家施莱登和动物学家施旺建立；核心内容：植物和动物都由细胞组成，细胞是生物体结构和功能的基本单位。", "mnemonic": "施莱登管植物，施旺管动物，合起来：细胞是基本单位。", "useImg": false}]}], "mcq": [{"id": "ch01_mcq_6", "mod": "模块二：发展历程(一)——进化论与细胞学说", "modI": 1, "q": "达尔文随贝格尔号军舰环球考察的时间是？", "o": ["A. 1825—1827年", "B. 1828—1831年", "C. 1831—1836年", "D. 1859—1882年"], "a": "C", "e": "达尔文于1831—1836年随贝格尔号军舰进行环球考察，为其进化论思想积累了大量证据。", "kp": "ch01_s1_0"}, {"id": "ch01_mcq_7", "mod": "模块二：发展历程(一)——进化论与细胞学说", "modI": 1, "q": "首次提出“cell”一词的科学家是？", "o": ["A. 列文虎克", "B. 罗伯特·胡克", "C. 施莱登", "D. 施旺"], "a": "B", "e": "1665年罗伯特·胡克在《显微图谱》中首次使用“cell”一词描述软木薄片中的小室。", "kp": "ch01_s1_5"}, {"id": "ch01_mcq_8", "mod": "模块二：发展历程(一)——进化论与细胞学说", "modI": 1, "q": "细胞学说的主要建立者是？", "o": ["A. 达尔文和胡克", "B. 列文虎克和胡克", "C. 施莱登和施旺", "D. 达尔文和施旺"], "a": "C", "e": "1838—1839年，施莱登和施旺分别研究植物和动物，共同提出细胞学说。", "kp": "ch01_s1_6"}, {"id": "ch01_mcq_9", "mod": "模块二：发展历程(一)——进化论与细胞学说", "modI": 1, "q": "细胞学说的核心内容不包括？", "o": ["A. 植物和动物都由细胞组成", "B. 细胞是生物体结构和功能的基本单位", "C. 细胞只能由已存在的细胞产生", "D. 细胞是生命活动的基本单位"], "a": "C", "e": "“细胞只能由已存在的细胞产生”是后来魏尔肖对细胞学说的补充，不属于施莱登和施旺最初提出的核心内容。", "kp": "ch01_s1_6"}, {"id": "ch01_mcq_10", "mod": "模块二：发展历程(一)——进化论与细胞学说", "modI": 1, "q": "达尔文进化论的核心思想可概括为？", "o": ["A. 上帝创造万物", "B. 物竞天择，适者生存", "C. 细胞是生命的基本单位", "D. 获得性遗传"], "a": "B", "e": "达尔文进化论以自然选择为核心，常概括为“物竞天择，适者生存”，从根基上动摇了“创世说”。", "kp": "ch01_s1_1"}], "judge": [{"id": "ch01_judge_2", "modI": 1, "q": "达尔文在《物种起源》中提出了以自然选择为核心的进化论。", "a": "对", "e": "1859年达尔文出版《物种起源》，提出以自然选择为核心的进化论，用“物竞天择，适者生存”解释物种起源与多样性。", "kp": "ch01_s1_1"}], "fill": [{"id": "ch01_fill_1", "modI": 1, "q": "1859年，达尔文发表《________》，奠定进化论基础。", "a": "物种起源", "kp": "ch01_s1_1"}], "short": [{"id": "ch01_short_3", "modI": 1, "q": "简述细胞学说的建立及其意义。", "a": "1. 1838—1839年，德国植物学家施莱登与动物学家施旺分别研究植物和动物组织；2. 提出植物和动物都由细胞组成；3. 细胞是生物体结构和功能的基本单位；4. 该学说与进化论、孟德尔遗传学并称现代生物学三大基石；5. 奠定细胞学发展基础，为分子生物学从细胞层次深入分子层次提供前提。", "kps": "", "kp": "ch01_s1_6"}], "calc": [], "term": [{"id": "ch01_term_2", "modI": 1, "term": "Natural Selection", "def": "自然选择：达尔文在《物种起源》中提出的进化论核心机制；以“物竞天择，适者生存”解释物种起源与多样性；从根基上动摇“创世说”，使生物学摆脱神学束缚。", "kps": "", "kp": "ch01_s1_5"}, {"id": "ch01_term_3", "modI": 1, "term": "Cell Theory", "def": "细胞学说：1838—1839年由德国植物学家施莱登和动物学家施旺提出；要点包括：植物和动物都由细胞组成；细胞是生物体结构和功能的基本单位；与进化论、孟德尔遗传学并称现代生物学三大基石。", "kps": "", "kp": "ch01_s1_5"}]}, {"i": 2, "name": "模块三：发展历程(二)——遗传学与染色体理论", "slides": [{"i": 0, "sec": "发展历程(二)——遗传学与染色体理论", "title": "孟德尔与遗传学的诞生 (p12)", "notes": "19世纪中叶，捷克布尔诺的神父孟德尔以豌豆为材料开展杂交实验，于1865年发表《植物杂交实验的遗传学定理》，提出前人未认识到的遗传规律，即孟德尔定律。然而其工作长期被忽视，直到1900年三位科学家分别重新发现这些定律，遗传学才正式诞生。孟德尔用数学统计方法分析生物学问题，开创了学科交叉的先河，被誉为遗传学之父。", "page": 12, "level": "掌握", "img": "assets/img/ch01/p012.jpg", "anim": null, "fig": null, "points": ["孟德尔以豌豆为材料开展杂交实验，1865年发表《植物杂交实验的遗传学定理》，提出孟德尔定律。", "孟德尔的工作长期被忽视，直到1900年三位科学家分别重新发现这些定律，遗传学才正式诞生。", "孟德尔用数学统计方法分析生物学问题，开创了学科交叉的先河，被誉为遗传学之父。"], "check": null, "cards": [{"front": "孟德尔用什么材料、何时发表、提出了什么定律？", "back": "以豌豆为材料，1865年发表《植物杂交实验的遗传学定理》，提出孟德尔定律（分离定律与自由组合定律）。", "mnemonic": "豌豆神父，1865，遗传学之父", "useImg": false}]}, {"i": 1, "sec": "发展历程(二)——遗传学与染色体理论", "title": "孟德尔研究的7对相对性状 (p13)", "notes": "孟德尔精心选择了豌豆的7对易于区分的相对性状：种子形状（饱满/皱缩）、种皮颜色（黄/绿）、花色（紫/白）、豆荚形状（不分节/分节）、豆荚颜色（绿/黄）、花着生位置（腋生/顶生）和植株高度（高/矮）。这些性状具有明显的显隐性关系，且豌豆自花授粉、易于人工杂交，为发现遗传规律提供了理想的实验材料。", "page": 13, "level": "理解", "img": "assets/img/ch01/p013.jpg", "anim": null, "fig": null, "points": ["孟德尔选择豌豆的7对易于区分的相对性状：种子形状、种皮颜色、花色、豆荚形状、豆荚颜色、花着生位置和植株高度。", "这些性状具有明显的显隐性关系。", "豌豆自花授粉、易于人工杂交，为发现遗传规律提供了理想的实验材料。"], "check": null, "cards": [{"front": "孟德尔的工作为何长期被忽视？何时被重新发现？", "back": "生前孤立于科学界，终生未被承认；1900年由三位科学家分别重新发现，遗传学才正式诞生。", "mnemonic": "生前寂寞，1900年三人重见天日", "useImg": false}]}, {"i": 2, "sec": "发展历程(二)——遗传学与染色体理论", "title": "孟德尔第一定律：分离定律 (p14)", "notes": "孟德尔发现子一代（F1）只表现显性性状，子二代（F2）中显性与隐性表型之比为3:1。他提出性状受成对的遗传因子控制，配子形成时成对因子彼此分离，分别进入不同配子，这就是分离定律。后来这些因子被称为基因，分离定律揭示了遗传的基本单位与传递规律，是遗传学第一定律。", "page": 14, "level": "掌握", "img": "assets/img/ch01/p014.jpg", "anim": null, "fig": null, "points": ["孟德尔发现子一代（F1）只表现显性性状，子二代（F2）中显性与隐性表型之比为3:1。", "提出性状受成对的遗传因子控制，配子形成时成对因子彼此分离，分别进入不同配子，即分离定律。", "后来这些因子被称为基因，分离定律揭示了遗传的基本单位与传递规律，是遗传学第一定律。"], "check": null, "cards": [{"front": "孟德尔选择豌豆的7对相对性状分别是什么？", "back": "种子形状（饱满/皱缩）、种皮颜色（黄/绿）、花色（紫/白）、豆荚形状（不分节/分节）、豆荚颜色（绿/黄）、花着生位置（腋生/顶生）、植株高度（高/矮）。", "mnemonic": "种形种色花色，荚形荚色花位株高", "useImg": false}]}, {"i": 3, "sec": "发展历程(二)——遗传学与染色体理论", "title": "孟德尔第二定律：自由组合定律 (p15)", "notes": "孟德尔进一步研究两对相对性状，发现子二代除亲本类型外还出现重组类型，且黄圆:黄皱:绿圆:绿皱接近9:3:3:1。他提出不同性状的遗传因子在配子形成时独立分配、自由组合，即自由组合定律。该定律揭示了非等位基因间的独立传递规律，为理解遗传变异和重组提供了理论基础。", "page": 15, "level": "掌握", "img": "assets/img/ch01/p015.jpg", "anim": null, "fig": null, "points": ["孟德尔研究两对相对性状，发现子二代出现重组类型，且黄圆:黄皱:绿圆:绿皱接近9:3:3:1。", "提出不同性状的遗传因子在配子形成时独立分配、自由组合，即自由组合定律。", "该定律揭示了非等位基因间的独立传递规律，为理解遗传变异和重组提供了理论基础。"], "check": null, "cards": [{"front": "孟德尔第一定律（分离定律）的核心内容是什么？", "back": "F1只表现显性性状，F2显性与隐性表型比为3:1；性状受成对遗传因子控制，配子形成时成对因子彼此分离，分别进入不同配子。", "mnemonic": "F1显，F2三比一；成对因子，配子分离", "useImg": false}]}, {"i": 4, "sec": "发展历程(二)——遗传学与染色体理论", "title": "孟德尔的孤独与遗产 (p16)", "notes": "孟德尔生前孤立于科学界，其奠基性发现终生未被承认。临终前他说：“等着瞧吧，我的时代总有一天会来临。”他是不为利益做研究的纯粹科学家，用数学分析生物，成功进行学科交叉。饶毅评价生物学有兩座智力高峰：1854—1866年孟德尔独自一人，1951—1965年克里克及其合作者，两个高峰相隔百年。", "page": 16, "level": "了解", "img": "assets/img/ch01/p016.jpg", "anim": null, "fig": null, "points": ["孟德尔生前孤立于科学界，其奠基性发现终生未被承认。", "临终前说：“等着瞧吧，我的时代总有一天会来临。”他是不为利益做研究的纯粹科学家。", "饶毅评价生物学有两座智力高峰：1854—1866年孟德尔独自一人，1951—1965年克里克及其合作者，两个高峰相隔百年。"], "check": null, "cards": [{"front": "孟德尔第二定律（自由组合定律）的核心内容是什么？", "back": "两对相对性状杂交，F2出现重组类型，黄圆:黄皱:绿圆:绿皱≈9:3:3:1；不同性状的遗传因子在配子形成时独立分配、自由组合。", "mnemonic": "两对性状，9:3:3:1；独立分配，自由组合", "useImg": false}]}, {"i": 5, "sec": "发展历程(二)——遗传学与染色体理论", "title": "孟德尔定律的重新发现 (p17)", "notes": "1900年，三位科学家——荷兰的德弗里斯（Hugo de Vries）、德国的科伦斯（Carl Correns）和奥地利的切尔马克（Erich von Tschermak）分别在不同植物中重新发现了孟德尔定律，使孟德尔的工作回到遗传学中心。这一事件标志着遗传学作为独立学科的诞生，也开启了染色体理论与遗传学结合的新阶段。", "page": 17, "level": "理解", "img": "assets/img/ch01/p017.jpg", "anim": null, "fig": null, "points": ["1900年，三位科学家——荷兰的德弗里斯、德国的科伦斯和奥地利的切尔马克分别在不同植物中重新发现了孟德尔定律。", "这一事件使孟德尔的工作回到遗传学中心，标志着遗传学作为独立学科的诞生。", "也开启了染色体理论与遗传学结合的新阶段。"], "check": null, "cards": [{"front": "孟德尔临终前说了什么？饶毅如何评价生物学智力高峰？", "back": "临终前说：“等着瞧吧，我的时代总有一天会来临。”饶毅认为生物学有两座智力高峰：1854—1866年孟德尔独自一人，1951—1965年克里克及其合作者，相隔百年。", "mnemonic": "我的时代会来临；两座高峰隔百年", "useImg": false}]}, {"i": 6, "sec": "发展历程(二)——遗传学与染色体理论", "title": "孤独的天才——孟德尔 (p18)", "notes": "孟德尔（1822-1884）自称为“实验物理学家”，是遗传学之父。他孤立于当时科学界，做出奠基性突破却终生未被承认；其工作几十年后仍不为一些重要科学家所理解；他发现的看似简单的理论，至今仍具深刻智力高度。他身后曾被疑造假，再遭不公。饶毅认为生物学两座智力高峰：孟德尔独自一人与克里克及其合作者，相隔百年。", "page": 18, "level": "了解", "img": "assets/img/ch01/p018.jpg", "anim": null, "fig": null, "points": ["孟德尔（1822-1884）自称为“实验物理学家”，是遗传学之父。", "他孤立于当时科学界，做出奠基性突破却终生未被承认；其工作几十年后仍不为一些重要科学家所理解。", "他发现的看似简单的理论，至今仍具深刻智力高度。", "饶毅认为生物学两座智力高峰：孟德尔独自一人与克里克及其合作者，相隔百年。"], "check": null, "cards": [{"front": "1900年重新发现孟德尔定律的三位科学家分别是谁？", "back": "荷兰的德弗里斯（Hugo de Vries）、德国的科伦斯（Carl Correns）、奥地利的切尔马克（Erich von Tschermak）。", "mnemonic": "德弗里斯、科伦斯、切尔马克——荷德奥三人", "useImg": false}]}, {"i": 7, "sec": "发展历程(二)——遗传学与染色体理论", "title": "基因一词的提出 (p19)", "notes": "1909年，丹麦植物学家约翰森（Wilhelm Johannsen）用“gene”一词描述孟德尔的“遗传因子”概念，并区分了基因型与表型。这一术语的提出使遗传学有了统一的核心概念，为后续基因与染色体关系的研究奠定了语言基础，也标志着遗传学从抽象因子向具体物质实体的过渡。", "page": 19, "level": "理解", "img": "assets/img/ch01/p019.jpg", "anim": null, "fig": null, "points": ["1909年，丹麦植物学家约翰森用“gene”一词描述孟德尔的“遗传因子”概念。", "并区分了基因型与表型。", "这一术语的提出使遗传学有了统一的核心概念，为后续基因与染色体关系的研究奠定了语言基础。", "标志着遗传学从抽象因子向具体物质实体的过渡。"], "check": null, "cards": [{"front": "孟德尔（1822-1884）自称什么？其工作有何特点？", "back": "自称“实验物理学家”，是遗传学之父；孤立于当时科学界，做出奠基性突破却终生未被承认，其理论至今仍具深刻智力高度。", "mnemonic": "实验物理学家，孤独的遗传学之父", "useImg": false}]}, {"i": 8, "sec": "发展历程(二)——遗传学与染色体理论", "title": "染色体在有丝分裂中的行为 (p20)", "notes": "染色体易被染色，在显微镜下清晰可见。人们感觉到它们在性状传递中起作用，但不知其机制。德国生物学家弗莱明（Walther Flemming）记录了染色体在有丝分裂中的行为，发现染色体复制并均等分配到子细胞。这为后来将基因与染色体联系起来提供了细胞学基础，是遗传的染色体理论的重要前提。", "page": 20, "level": "理解", "img": "assets/img/ch01/p020.jpg", "anim": null, "fig": null, "points": ["染色体易被染色，在显微镜下清晰可见。", "德国生物学家弗莱明记录了染色体在有丝分裂中的行为，发现染色体复制并均等分配到子细胞。", "这为后来将基因与染色体联系起来提供了细胞学基础，是遗传的染色体理论的重要前提。"], "check": null, "cards": [{"front": "“gene”一词由谁在何时提出？他还区分了什么？", "back": "1909年丹麦植物学家约翰森（Wilhelm Johannsen）提出，用“gene”描述孟德尔的“遗传因子”，并区分了基因型与表型。", "mnemonic": "1909约翰森，gene+基因型/表型", "useImg": false}]}, {"i": 9, "sec": "发展历程(二)——遗传学与染色体理论", "title": "摩尔根果蝇实验：基因在染色体上 (p21)", "notes": "1910年，摩尔根通过果蝇杂交实验，将基因与染色体联系起来，证明基因位于染色体上。他因此获得诺贝尔奖，获奖理由是“发现染色体在遗传中的作用”。果蝇实验揭示了伴性遗传等现象，为遗传的染色体理论提供了直接证据，使遗传学从抽象规律走向具体物质基础。", "page": 21, "level": "掌握", "img": "assets/img/ch01/p021.jpg", "anim": null, "fig": null, "points": ["1910年，摩尔根通过果蝇杂交实验，将基因与染色体联系起来，证明基因位于染色体上。", "他因此获得诺贝尔奖，获奖理由是“发现染色体在遗传中的作用”。", "果蝇实验揭示了伴性遗传等现象，为遗传的染色体理论提供了直接证据。", "使遗传学从抽象规律走向具体物质基础。"], "check": null, "cards": [{"front": "谁记录了染色体在有丝分裂中的行为？发现了什么？", "back": "德国生物学家弗莱明（Walther Flemming）记录了染色体在有丝分裂中的行为，发现染色体复制并均等分配到子细胞。", "mnemonic": "弗莱明看有丝分裂：复制+均等分配", "useImg": false}]}, {"i": 10, "sec": "发展历程(二)——遗传学与染色体理论", "title": "基因座、等位基因与纯合/杂合 (p22)", "notes": "在一个物种中，每个基因在染色体上有自己的位置，即基因座（locus）。同一基因座上的不同形式称为等位基因（alleles）。二倍体生物的染色体通常成对存在，形成同源染色体，同源染色体上具有相对应的基因座。若同源染色体上等位基因相同则为纯合子（homozygote），不同则为杂合子（heterozygote）。", "page": 22, "level": "掌握", "img": "assets/img/ch01/p022.jpg", "anim": null, "fig": null, "points": ["在一个物种中，每个基因在染色体上有自己的位置，即基因座（locus）。", "同一基因座上的不同形式称为等位基因（alleles）。", "二倍体生物的染色体通常成对存在，形成同源染色体，同源染色体上具有相对应的基因座。", "若同源染色体上等位基因相同则为纯合子（homozygote），不同则为杂合子（heterozygote）。"], "check": null, "cards": [{"front": "摩尔根通过什么实验证明了什么？因此获得什么奖？", "back": "1910年通过果蝇杂交实验，证明基因位于染色体上；获诺贝尔奖，获奖理由是“发现染色体在遗传中的作用”。", "mnemonic": "果蝇实验，基因在染色体上；诺奖理由：染色体在遗传中的作用", "useImg": false}]}, {"i": 11, "sec": "发展历程(二)——遗传学与染色体理论", "title": "果蝇的染色体与突变体 (p23)", "notes": "果蝇有四对染色体，数量少、形状差别明显，便于研究。野生型果蝇为红眼、长翅；突变体则表现眼睛颜色（白、橙）、翅膀形状（残、短、卷）、身体颜色（黄、乌木）、头部形态（无眼、触角腿）等变异。这些突变体为摩尔根研究基因与染色体的关系提供了丰富的实验材料，推动了遗传的染色体理论发展。", "page": 23, "level": "理解", "img": "assets/img/ch01/p023.jpg", "anim": null, "fig": null, "points": ["果蝇有四对染色体，数量少、形状差别明显，便于研究。", "野生型果蝇为红眼、长翅；突变体则表现眼睛颜色、翅膀形状、身体颜色、头部形态等变异。", "这些突变体为摩尔根研究基因与染色体的关系提供了丰富的实验材料，推动了遗传的染色体理论发展。"], "check": null, "cards": [{"front": "什么是基因座、等位基因、纯合子和杂合子？", "back": "基因座（locus）：基因在染色体上的位置；等位基因（alleles）：同一基因座上的不同形式；纯合子（homozygote）：同源染色体上等位基因相同；杂合子（heterozygote）：同源染色体上等位基因不同。", "mnemonic": "座位=基因座，同座不同=等位；相同纯合，不同杂合", "useImg": false}]}, {"i": 12, "sec": "发展历程(二)——遗传学与染色体理论", "title": "摩尔根的果蝇遗传连锁图 (p24)", "notes": "摩尔根绘制了第一个成功的遗传图谱，为遗传的染色体理论提供了重要证据。该图显示果蝇第二条染色体上等位基因的相对位置。基因之间的距离以摩厘（centimorgans）表示，等于染色体交换事件的百分比。两个基因间重组频率越大，距离越远；重组频率越小，距离越近。这一定量关系使基因定位成为可能。", "page": 24, "level": "掌握", "img": "assets/img/ch01/p024.jpg", "anim": null, "fig": null, "points": ["摩尔根绘制了第一个成功的遗传图谱，为遗传的染色体理论提供了重要证据。", "该图显示果蝇第二条染色体上等位基因的相对位置。", "基因之间的距离以摩厘（centimorgans）表示，等于染色体交换事件的百分比。", "两个基因间重组频率越大，距离越远；重组频率越小，距离越近。这一定量关系使基因定位成为可能。"], "check": null, "cards": [{"front": "果蝇作为模式生物有哪些优势？有哪些常见突变体？", "back": "有四对染色体，数量少、形状差别明显，便于研究。野生型为红眼、长翅；突变体有眼睛颜色（白、橙）、翅膀形状（残、短、卷）、身体颜色（黄、乌木）、头部形态（无眼、触角腿）等。", "mnemonic": "四对染色体，红眼长翅；白橙眼、残短卷翅、黄乌木身、无眼触角腿", "useImg": false}]}, {"i": 13, "sec": "发展历程(二)——遗传学与染色体理论", "title": "摩尔根的基因论——三位一体 (p25)", "notes": "摩尔根提出基因论，认为基因确切存在，呈线状排列在染色体上，决定某一特定性状，并可突变和交换。基因是功能单位、突变单位和重组单位，三位一体。这一理论将基因从抽象概念变为染色体上的实体，奠定了经典遗传学的核心框架，对后续分子生物学的发展具有深远影响。", "page": 25, "level": "掌握", "img": "assets/img/ch01/p025.jpg", "anim": null, "fig": null, "points": ["摩尔根提出基因论，认为基因确切存在，呈线状排列在染色体上，决定某一特定性状，并可突变和交换。", "基因是功能单位、突变单位和重组单位，三位一体。", "这一理论将基因从抽象概念变为染色体上的实体，奠定了经典遗传学的核心框架。", "对后续分子生物学的发展具有深远影响。"], "check": null, "cards": [{"front": "摩尔根绘制的遗传连锁图有何意义？距离单位是什么？", "back": "绘制了第一个成功的遗传图谱，为遗传的染色体理论提供重要证据；显示果蝇第二条染色体上等位基因的相对位置，距离以摩厘（centimorgans）表示，等于染色体交换事件的百分比。", "mnemonic": "第一张遗传图谱；摩厘=交换百分比", "useImg": false}]}, {"i": 14, "sec": "发展历程(二)——遗传学与染色体理论", "title": "遗传重组与图谱 (p26)", "notes": "在果蝇中，雌蝇的两条X染色体分别携带野生型基因（m+全翅、w+红眼）和突变型基因（m残翅、w白眼）。在卵形成过程中，两条染色体上的这两个基因之间会发生重组或交叉，产生重组型配子。重组频率可用于绘制遗传图谱，重组率越高，基因间距离越远。这一现象揭示了染色体交换的遗传学效应。", "page": 26, "level": "理解", "img": "assets/img/ch01/p026.jpg", "anim": null, "fig": null, "points": ["在果蝇中，雌蝇的两条X染色体分别携带野生型基因（m+全翅、w+红眼）和突变型基因（m残翅、w白眼）。", "在卵形成过程中，两条染色体上的这两个基因之间会发生重组或交叉，产生重组型配子。", "重组频率可用于绘制遗传图谱，重组率越高，基因间距离越远。", "这一现象揭示了染色体交换的遗传学效应。"], "check": null, "cards": [{"front": "摩尔根的基因论（三位一体）核心内容是什么？", "back": "基因确切存在，呈线状排列在染色体上，决定某一特定性状，并可突变和交换；基因是功能单位、突变单位和重组单位，三位一体。", "mnemonic": "线状排列在染色体；功能+突变+重组，三位一体", "useImg": false}]}, {"i": 15, "sec": "发展历程(二)——遗传学与染色体理论", "title": "遗传重组的物理证据 (p27)", "notes": "1931年，麦克林托克（Barbara McClintock）和克赖顿（Harriet Creighton）在玉米中直接证明了重组现象，之后在果蝇中也观察到同样现象。麦克林托克后来发现转座子，于1983年获得诺贝尔生理学或医学奖，时年81岁。19世纪下半叶到20世纪上半叶，遗传学界有三位伟大科学家姓氏均以M开头：孟德尔、摩尔根和麦克林托克。", "page": 27, "level": "理解", "img": "assets/img/ch01/p027.jpg", "anim": null, "fig": null, "points": ["1931年，麦克林托克和克赖顿在玉米中直接证明了重组现象，之后在果蝇中也观察到同样现象。", "麦克林托克后来发现转座子，于1983年获得诺贝尔生理学或医学奖，时年81岁。", "19世纪下半叶到20世纪上半叶，遗传学界有三位伟大科学家姓氏均以M开头：孟德尔、摩尔根和麦克林托克。"], "check": null, "cards": [{"front": "遗传重组的物理证据由谁在何时提供？她后来还有什么发现？", "back": "1931年麦克林托克（Barbara McClintock）和克赖顿（Harriet Creighton）在玉米中直接证明重组现象，之后在果蝇中也观察到；麦克林托克后来发现转座子，1983年获诺贝尔生理学或医学奖，时年81岁。", "mnemonic": "玉米重组1931；转座子1983诺奖，81岁", "useImg": false}]}, {"i": 16, "sec": "发展历程(二)——遗传学与染色体理论", "title": "早期遗传学的研究范式 (p28)", "notes": "早期遗传学家通过分析突变体在世代间的传递规律，研究基因特性和染色体定位，描述基因突变和染色体变异效应。在不知基因化学本质的前提下，遗传学依靠逻辑分析的推理性科学方法，即正向遗传学（Forward Genetics）。这一范式为后来分子生物学的诞生奠定了方法论基础。", "page": 28, "level": "理解", "img": "assets/img/ch01/p028.jpg", "anim": null, "fig": null, "points": ["早期遗传学家通过分析突变体在世代间的传递规律，研究基因特性和染色体定位，描述基因突变和染色体变异效应。", "在不知基因化学本质的前提下，遗传学依靠逻辑分析的推理性科学方法，即正向遗传学（Forward Genetics）。", "这一范式为后来分子生物学的诞生奠定了方法论基础。"], "check": null, "cards": [{"front": "早期遗传学的研究范式（正向遗传学）是什么？", "back": "通过分析突变体在世代间的传递规律，研究基因特性和染色体定位，描述基因突变和染色体变异效应；在不知基因化学本质的前提下，依靠逻辑分析的推理性科学方法，即正向遗传学（Forward Genetics）。", "mnemonic": "从突变体表型反推基因——正向遗传学", "useImg": false}]}], "mcq": [{"id": "ch01_mcq_11", "mod": "模块三：发展历程(二)——遗传学与染色体理论", "modI": 2, "q": "孟德尔于哪一年发表《植物杂交实验的遗传学定理》？", "o": ["A. 1859年", "B. 1865年", "C. 1900年", "D. 1910年"], "a": "B", "e": "孟德尔于1865年发表《植物杂交实验的遗传学定理》，提出孟德尔定律。1900年三位科学家重新发现该定律，遗传学正式诞生。", "kp": "ch01_s2_0"}, {"id": "ch01_mcq_12", "mod": "模块三：发展历程(二)——遗传学与染色体理论", "modI": 2, "q": "孟德尔第一定律（分离定律）中，子二代显性与隐性表型的比值是？", "o": ["A. 1:1", "B. 2:1", "C. 3:1", "D. 9:3:3:1"], "a": "C", "e": "孟德尔发现子二代中显性表型与隐性表型的比值为3:1，据此提出分离定律。9:3:3:1是两对性状自由组合的典型比例。", "kp": "ch01_s2_2"}, {"id": "ch01_mcq_13", "mod": "模块三：发展历程(二)——遗传学与染色体理论", "modI": 2, "q": "1909年提出“gene”一词描述孟德尔“遗传因子”概念的科学家是？", "o": ["A. 摩尔根", "B. 约翰森", "C. 弗莱明", "D. 德弗里斯"], "a": "B", "e": "1909年丹麦植物学家约翰森用“gene”一词描述孟德尔的“遗传因子”概念，并区分了基因型与表型。", "kp": "ch01_s2_7"}, {"id": "ch01_mcq_14", "mod": "模块三：发展历程(二)——遗传学与染色体理论", "modI": 2, "q": "摩尔根通过果蝇实验证明基因位于染色体上，他获得诺贝尔奖的理由是？", "o": ["A. 发现DNA双螺旋结构", "B. 发现染色体在遗传中的作用", "C. 发现转座子", "D. 提出中心法则"], "a": "B", "e": "摩尔根因“发现染色体在遗传中的作用”获得诺贝尔奖，他通过果蝇实验证明基因位于染色体上，为遗传的染色体理论提供直接证据。", "kp": "ch01_s2_9"}, {"id": "ch01_mcq_15", "mod": "模块三：发展历程(二)——遗传学与染色体理论", "modI": 2, "q": "关于摩尔根的基因论，下列哪项不正确？", "o": ["A. 基因呈线状排列在染色体上", "B. 基因是功能单位、突变单位和重组单位", "C. 基因不可突变", "D. 基因可交换"], "a": "C", "e": "摩尔根基因论认为基因可突变、可交换，是功能单位、突变单位和重组单位三位一体。选项C“基因不可突变”与基因论相悖。", "kp": "ch01_s2_13"}], "judge": [{"id": "ch01_judge_3", "modI": 2, "q": "孟德尔第一定律是自由组合定律，第二定律是分离定律。", "a": "错", "e": "孟德尔第一定律是分离定律，第二定律是自由组合定律。", "kp": "ch01_s2_3"}, {"id": "ch01_judge_4", "modI": 2, "q": "孟德尔在1865年发表《植物杂交实验》，其工作当时即被科学界广泛承认。", "a": "错", "e": "孟德尔工作长期被忽视，直到1900年三位科学家分别重新发现这些定律，遗传学才正式诞生。", "kp": "ch01_s2_0"}, {"id": "ch01_judge_5", "modI": 2, "q": "1909年约翰森用“gene”一词描述孟德尔的“遗传因子”概念，并区分了基因型与表型。", "a": "对", "e": "讲义指出1909年丹麦植物学家约翰森用“gene”一词描述孟德尔的“遗传因子”概念，并区分了基因型与表型。", "kp": "ch01_s2_7"}, {"id": "ch01_judge_6", "modI": 2, "q": "摩尔根通过果蝇杂交实验证明基因位于染色体上，并获得诺贝尔奖。", "a": "对", "e": "1910年摩尔根通过果蝇杂交实验将基因与染色体联系起来，证明基因位于染色体上，获奖理由是“发现染色体在遗传中的作用”。", "kp": "ch01_s2_9"}, {"id": "ch01_judge_7", "modI": 2, "q": "同一基因座上的不同形式称为等位基因。", "a": "对", "e": "讲义指出同一基因座上的不同形式称为等位基因。", "kp": "ch01_s2_10"}], "fill": [{"id": "ch01_fill_2", "modI": 2, "q": "1865年，孟德尔发表《________》，揭示遗传规律。", "a": "植物杂交实验", "kp": "ch01_s2_0"}, {"id": "ch01_fill_3", "modI": 2, "q": "1910年，摩尔根通过________杂交实验将基因定位到染色体。", "a": "果蝇", "kp": "ch01_s2_9"}, {"id": "ch01_fill_6", "modI": 2, "q": "孟德尔第一定律又称________，F2中显性与隐性表型之比为________。", "a": "分离定律,3:1", "kp": "ch01_s2_2"}, {"id": "ch01_fill_7", "modI": 2, "q": "孟德尔第二定律又称________，两对相对性状F2表型比接近________。", "a": "自由组合定律,9:3:3:1", "kp": "ch01_s2_3"}, {"id": "ch01_fill_8", "modI": 2, "q": "1909年，丹麦植物学家约翰森用“________”一词描述孟德尔的“遗传因子”概念。", "a": "gene", "kp": "ch01_s2_7"}], "short": [{"id": "ch01_short_4", "modI": 2, "q": "简述摩尔根基因论的主要内容。", "a": "1. 基因确切存在；2. 基因呈线状排列在染色体上；3. 基因决定某一特定性状；4. 基因可突变和交换；5. 基因是功能单位、突变单位和重组单位，三位一体；6. 将基因从抽象概念变为染色体上的实体，奠定经典遗传学核心框架。", "kps": "", "kp": "ch01_s2_13"}], "calc": [{"id": "ch01_calc_1", "modI": 2, "q": "论述孟德尔遗传定律的发现过程、主要内容及其对分子生物学的意义。", "a": "孟德尔以豌豆为材料开展杂交实验，1865年发表《植物杂交实验的遗传学定理》，提出分离定律和自由组合定律。分离定律：F1只表现显性性状，F2显性与隐性表型之比为3:1；性状受成对遗传因子控制，配子形成时成对因子彼此分离，分别进入不同配子。自由组合定律：两对相对性状F2出现重组类型，黄圆:黄皱:绿圆:绿皱接近9:3:3:1；不同性状的遗传因子在配子形成时独立分配、自由组合。意义：孟德尔用数学统计方法分析生物学问题，开创学科交叉先河；其工作长期被忽视，1900年三位科学家重新发现，遗传学正式诞生；为基因概念、染色体理论和分子遗传学奠定基础。", "steps": "1. 实验材料与时间；2. 分离定律要点；3. 自由组合定律要点；4. 数学统计与学科交叉；5. 重新发现与遗传学诞生；6. 对分子生物学的意义。", "kp": "ch01_s2_5"}], "term": [{"id": "ch01_term_4", "modI": 2, "term": "Mendel's Law of Segregation", "def": "孟德尔第一定律/分离定律：孟德尔以豌豆杂交实验发现；F1只表现显性性状，F2显性与隐性表型之比为3:1；性状受成对遗传因子控制；配子形成时成对因子彼此分离，分别进入不同配子；揭示遗传的基本单位与传递规律。", "kps": "", "kp": "ch01_s2_5"}, {"id": "ch01_term_5", "modI": 2, "term": "Mendel's Law of Independent Assortment", "def": "孟德尔第二定律/自由组合定律：孟德尔研究两对相对性状发现；F2除亲本类型外出现重组类型，黄圆:黄皱:绿圆:绿皱接近9:3:3:1；不同性状的遗传因子在配子形成时独立分配、自由组合；揭示非等位基因间的独立传递规律。", "kps": "", "kp": "ch01_s2_5"}, {"id": "ch01_term_6", "modI": 2, "term": "Gene", "def": "基因：1909年丹麦植物学家约翰森用“gene”描述孟德尔的“遗传因子”概念；并区分基因型与表型；使遗传学有统一核心概念；为基因与染色体关系研究奠定语言基础；标志遗传学从抽象因子向具体物质实体过渡。", "kps": "", "kp": "ch01_s2_16"}, {"id": "ch01_term_7", "modI": 2, "term": "Locus", "def": "基因座：在一个物种中，每个基因在染色体上有自己的位置；同一基因座上的不同形式称为等位基因；二倍体生物染色体通常成对存在，形成同源染色体，同源染色体上具有相对应的基因座。", "kps": "", "kp": "ch01_s2_10"}, {"id": "ch01_term_8", "modI": 2, "term": "Allele", "def": "等位基因：同一基因座上的不同形式；二倍体生物同源染色体上具有相对应的基因座；若同源染色体上等位基因相同则为纯合子，不同则为杂合子。", "kps": "", "kp": "ch01_s2_10"}, {"id": "ch01_term_9", "modI": 2, "term": "Homozygote / Heterozygote", "def": "纯合子/杂合子：二倍体生物染色体成对存在，形成同源染色体；同源染色体上等位基因相同为纯合子；同源染色体上等位基因不同为杂合子。", "kps": "", "kp": "ch01_s2_10"}, {"id": "ch01_term_10", "modI": 2, "term": "Forward Genetics", "def": "正向遗传学：早期遗传学的研究范式；通过分析突变体在世代间的传递规律，研究基因特性和染色体定位；描述基因突变和染色体变异效应；在不知基因化学本质的前提下，依靠逻辑分析的推理性科学方法。", "kps": "", "kp": "ch01_s2_16"}]}, {"i": 3, "name": "模块四：发展历程(三)——生物化学与DNA的发现", "slides": [{"i": 0, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "生物化学的快速发展(p29)", "notes": "19世纪末至20世纪中期，生物化学进入快速发展阶段。这一时期，组成蛋白质的20种基本氨基酸被逐一揭示，连接氨基酸的肽键得到证实，糖酵解途径、尿素循环、三羧酸循环等主要代谢途径相继发现。同时，pH概念、缓冲系统和胶体理论被提出，大分子之间以氢键和离子键相互作用的重要性也被阐明。这些成果为后来分子生物学的诞生奠定了坚实的化学基础，使人们开始从分子层面理解生命现象。", "page": 29, "level": "理解", "img": "assets/img/ch01/p029.jpg", "anim": null, "fig": null, "points": ["19世纪末至20世纪中期生物化学快速发展", "20种基本氨基酸被逐一揭示，肽键得到证实", "糖酵解途径、尿素循环、三羧酸循环等主要代谢途径相继发现", "pH概念、缓冲系统和胶体理论被提出", "为分子生物学诞生奠定化学基础"], "check": null, "cards": [{"front": "19世纪末至20世纪中期，生物化学快速发展时期有哪些主要成果？", "back": "揭示20种基本氨基酸、证实肽键、发现糖酵解、尿素循环、三羧酸循环等代谢途径；提出pH、缓冲系统、胶体理论；阐明氢键和离子键在大分子相互作用中的重要性。", "mnemonic": "氨基酸肽键代谢路，pH缓冲胶体助，氢键离子大分子", "useImg": false}]}, {"i": 1, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "酶与病毒蛋白的纯化及结晶(p30)", "notes": "1946年诺贝尔化学奖授予James Batcheller Sumner、John Howard Northrop和Wendell Meredith Stanley，以表彰他们制备纯酶和病毒蛋白的工作。Sumner证明酶可以结晶，Northrop和Stanley分别纯化了多种酶和病毒蛋白。这些工作表明酶是蛋白质，病毒蛋白也可结晶，从而推动了蛋白质化学的发展，并为后续研究蛋白质结构与功能关系提供了重要材料和方法。", "page": 30, "level": "了解", "img": "assets/img/ch01/p030.jpg", "anim": null, "fig": null, "points": ["1946年诺贝尔化学奖授予Sumner、Northrop和Stanley", "Sumner证明酶可以结晶", "Northrop和Stanley分别纯化了多种酶和病毒蛋白", "表明酶是蛋白质，病毒蛋白也可结晶", "推动蛋白质化学发展，为蛋白质结构与功能研究提供基础"], "check": null, "cards": [{"front": "1946年诺贝尔化学奖授予Sumner、Northrop和Stanley的原因是什么？", "back": "表彰他们制备纯酶和病毒蛋白的工作。Sumner证明酶可以结晶，Northrop和Stanley分别纯化了多种酶和病毒蛋白，表明酶是蛋白质。", "mnemonic": "三氏结晶酶与毒，酶是蛋白得证实", "useImg": false}]}, {"i": 2, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "噬菌体转导与胰岛素蛋白结构解析(p31)", "notes": "J. Lederberg发现噬菌体转导现象，即噬菌体可将供体菌的基因转移给受体菌，这是细菌遗传学的重要发现，获得1958年诺贝尔生理学或医学奖。Frederick Sanger则因对蛋白质结构尤其是胰岛素结构的研究获得1958年诺贝尔化学奖，他首次测定了胰岛素的一级结构，证明蛋白质具有确定的氨基酸序列，为分子生物学提供了重要技术范例。", "page": 31, "level": "理解", "img": "assets/img/ch01/p031.jpg", "anim": null, "fig": null, "points": ["J. Lederberg发现噬菌体转导现象，获1958年诺贝尔生理学或医学奖", "噬菌体可将供体菌基因转移给受体菌", "Frederick Sanger获1958年诺贝尔化学奖", "Sanger首次测定胰岛素一级结构", "证明蛋白质具有确定的氨基酸序列"], "check": null, "cards": [{"front": "J. Lederberg发现了什么现象？获得什么奖？", "back": "发现噬菌体转导现象，即噬菌体可将供体菌的基因转移给受体菌。获得1958年诺贝尔生理学或医学奖。", "mnemonic": "噬菌转导基因移，Lederberg五八奖", "useImg": false}]}, {"i": 3, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "一个基因一条多肽链(p32)", "notes": "1941年，George Beadle和Edward Tatum提出“一个基因一个酶”假说，认为基因的生化作用本质是控制酶的合成，该假说获得1958年诺贝尔生理学或医学奖。后来这一概念被修正为“一个基因一条多肽链”。Archibald Garrod早在1911年就提出先天性代谢缺陷与酶缺陷有关，为这一假说提供了先导性思想。该假说将基因与蛋白质功能直接联系起来，是分子生物学发展的重要里程碑。", "page": 32, "level": "掌握", "img": "assets/img/ch01/p032.jpg", "anim": null, "fig": null, "points": ["1941年Beadle和Tatum提出“一个基因一个酶”假说", "获1958年诺贝尔生理学或医学奖", "后修正为“一个基因一条多肽链”", "Garrod 1911年提出先天性代谢缺陷与酶缺陷有关", "将基因与蛋白质功能直接联系，是重要里程碑"], "check": null, "cards": [{"front": "Frederick Sanger因什么研究获得1958年诺贝尔化学奖？", "back": "因对蛋白质结构尤其是胰岛素结构的研究获奖，他首次测定了胰岛素的一级结构，证明蛋白质具有确定的氨基酸序列。", "mnemonic": "Sanger测序胰岛素，一级结构定序列", "useImg": false}]}, {"i": 4, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "DNA的发现：肺炎链球菌转化实验(p33)", "notes": "1928年，英国科学家Frederick Griffith在研究肺炎链球菌时发现，将加热杀死的光滑型（S型）菌与粗糙型（R型）活菌混合注射小鼠，可导致小鼠死亡并分离出S型活菌。这表明死菌中某种物质使R型菌转化为S型菌，即“转化”现象。该实验首次揭示了遗传信息可以在细菌之间传递，为后来证明DNA是遗传物质提供了关键线索。", "page": 33, "level": "掌握", "img": "assets/img/ch01/p033.jpg", "anim": null, "fig": null, "points": ["1928年Griffith发现肺炎链球菌转化现象", "加热杀死的S型菌与R型活菌混合注射小鼠导致死亡", "从死亡小鼠分离出S型活菌", "表明死菌中某种物质使R型菌转化为S型菌", "首次揭示遗传信息可在细菌间传递"], "check": null, "cards": [{"front": "“一个基因一个酶”假说由谁提出？后来被修正为什么？", "back": "1941年由George Beadle和Edward Tatum提出，认为基因的生化作用本质是控制酶的合成。后来被修正为“一个基因一条多肽链”。", "mnemonic": "Beadle Tatum一基因一酶，修正为一条多肽链", "useImg": false}]}, {"i": 5, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "转化现象及其意义(p34)", "notes": "转化是指遗传物质在两个完全不相关的陌生个体间传递，属于水平基因交换。转化现象几乎不发生在哺乳动物中，但可发生在细菌中。与之相对的是垂直遗传，即基因从父母到孩子或从母细胞到子细胞。Griffith于1928年1月在《卫生学杂志》发表实验数据，其意义在于表明遗传信息（基因）是以某种化学形式在两种菌株之间传递，即基因是一种化学物质。", "page": 34, "level": "掌握", "img": "assets/img/ch01/p034.jpg", "anim": null, "fig": null, "points": ["转化是遗传物质在两个完全不相关陌生个体间传递，属水平基因交换", "转化几乎不发生在哺乳动物中，但可发生在细菌中", "垂直遗传指基因从父母到孩子或从母细胞到子细胞", "Griffith于1928年1月在《卫生学杂志》发表实验数据", "表明基因是一种化学物质"], "check": null, "cards": [{"front": "Archibald Garrod对“一个基因一个酶”假说有何贡献？", "back": "1911年提出先天性代谢缺陷与酶缺陷有关，为该假说提供了先导性思想。", "mnemonic": "Garrod先天代谢缺，酶缺陷是先导思", "useImg": false}]}, {"i": 6, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "Avery等证明DNA是转化因子(p35)", "notes": "1944年，Oswald T. Avery、Maclyn McCarty和Colin MacLeod在Griffith实验基础上，系统寻找转化因子。他们将S型菌的各种物质分开，单独观察其转化活性，确定唯一变量。结果发现只有DNA能引起转化，而蛋白酶、RNA酶等不能破坏转化活性，DNA酶则可使其失活。从而证明DNA是转化因子，即遗传物质。这一工作奠定了“DNA是遗传物质”的理论基础。", "page": 35, "level": "掌握", "img": "assets/img/ch01/p035.jpg", "anim": null, "fig": null, "points": ["1944年Avery、McCarty和MacLeod在Griffith实验基础上寻找转化因子", "将S型菌各种物质分开，单独观察转化活性，确定唯一变量", "只有DNA能引起转化", "蛋白酶、RNA酶不能破坏转化活性，DNA酶可使其失活", "证明DNA是转化因子，即遗传物质"], "check": null, "cards": [{"front": "Griffith的肺炎链球菌转化实验（1928年）发现了什么？", "back": "将加热杀死的光滑型（S型）菌与粗糙型（R型）活菌混合注射小鼠，导致小鼠死亡并分离出S型活菌，表明死菌中某种物质使R型菌转化为S型菌，即“转化”现象。", "mnemonic": "死S加活R，小鼠死亡出S，转化现象首揭示", "useImg": false}]}, {"i": 7, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "16年肺炎链球菌遗传转化研究的意义(p36)", "notes": "1928年至1944年，经过16年的肺炎链球菌遗传转化研究，Avery等人证明DNA是转化因子。当时科学家对核酸了解甚少，DNA分子的功能不为人熟悉，且普遍认为蛋白质可能是遗传专一性的决定分子。因此，该发现第一个动摇了“蛋白质是基因”的理念，奠定了“DNA是遗传物质”的理论基础。尽管当时仍有质疑，但它标志着分子生物学的重要转折。", "page": 36, "level": "掌握", "img": "assets/img/ch01/p036.jpg", "anim": null, "fig": null, "points": ["1928年至1944年，16年肺炎链球菌遗传转化研究", "Avery等证明DNA是转化因子", "当时普遍认为蛋白质可能是遗传专一性的决定分子", "第一个动摇了“蛋白质是基因”的理念", "奠定“DNA是遗传物质”的理论基础，标志分子生物学重要转折"], "check": null, "cards": [{"front": "什么是转化？其意义是什么？", "back": "转化是指遗传物质在两个完全不相关的陌生个体间传递，属于水平基因交换。意义在于表明遗传信息（基因）是以某种化学形式在两种菌株之间传递，即基因是一种化学物质。", "mnemonic": "转化水平传基因，基因本是化学物", "useImg": false}]}, {"i": 8, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "Hershey-Chase噬菌体实验(p37)", "notes": "1952年，Alfred Hershey和Martha Chase利用噬菌体（细菌病毒）进行实验。噬菌体由蛋白质外壳和DNA核心组成，感染细菌时只有DNA进入宿主细胞。他们分别用放射性同位素32P标记DNA、35S标记蛋白质，追踪感染后放射性去向。结果发现32P进入细菌并传递给子代噬菌体，而35S留在菌体外。该实验有力证明DNA是主要的遗传物质，获得1969年诺贝尔生理学或医学奖。", "page": 37, "level": "掌握", "img": "assets/img/ch01/p037.jpg", "anim": null, "fig": null, "points": ["1952年Hershey和Chase利用噬菌体进行实验", "噬菌体由蛋白质外壳和DNA核心组成，感染时只有DNA进入宿主细胞", "用32P标记DNA、35S标记蛋白质，追踪感染后放射性去向", "32P进入细菌并传递给子代噬菌体，35S留在菌体外", "有力证明DNA是主要遗传物质，获1969年诺贝尔生理学或医学奖"], "check": null, "cards": [{"front": "Avery、McCarty和MacLeod（1944年）如何证明DNA是转化因子？", "back": "将S型菌的各种物质分开，单独观察转化活性。结果只有DNA能引起转化，蛋白酶和RNA酶不能破坏转化活性，DNA酶则可使其失活，从而证明DNA是转化因子即遗传物质。", "mnemonic": "分离物质单独试，DNA转化酶失活", "useImg": false}]}, {"i": 9, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "Hershey-Chase实验原理与结果(p38)", "notes": "Hershey-Chase实验利用噬菌体T2感染大肠杆菌。噬菌体吸附后，将DNA注入细菌，蛋白质外壳留在外面。通过搅拌使外壳脱落，离心后细菌沉淀，外壳在上清。32P标记的DNA出现在沉淀中，35S标记的蛋白质出现在上清中。子代噬菌体中含有32P而不含35S。这一结果直接证明DNA是遗传物质，蛋白质不是。该实验设计巧妙，成为分子生物学经典实验之一。", "page": 38, "level": "掌握", "img": "assets/img/ch01/p038.jpg", "anim": null, "fig": null, "points": ["Hershey-Chase实验利用噬菌体T2感染大肠杆菌", "噬菌体吸附后将DNA注入细菌，蛋白质外壳留在外面", "搅拌使外壳脱落，离心后细菌沉淀，外壳在上清", "32P标记的DNA出现在沉淀中，35S标记的蛋白质出现在上清中", "子代噬菌体含32P不含35S，直接证明DNA是遗传物质，蛋白质不是"], "check": null, "cards": [{"front": "16年肺炎链球菌遗传转化研究的意义是什么？", "back": "第一个动摇了“蛋白质是基因”的理念，奠定了“DNA是遗传物质”的理论基础，标志着分子生物学的重要转折。", "mnemonic": "十六年研究动蛋白，DNA遗传奠基础", "useImg": false}]}, {"i": 10, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "DNA是主要遗传物质的证明(p39)", "notes": "Hershey-Chase实验以及Avery等人的工作共同证明DNA是主要的遗传物质。此后，1953年Watson和Crick提出DNA双螺旋结构模型，进一步阐明了DNA如何储存和复制遗传信息。这些发现将遗传学与生物化学统一起来，催生了分子生物学这一学科。DNA作为遗传物质的地位得以确立，为基因克隆、基因工程等现代生物技术奠定了基础。", "page": 39, "level": "掌握", "img": "assets/img/ch01/p039.jpg", "anim": null, "fig": null, "points": ["Hershey-Chase实验以及Avery等的工作共同证明DNA是主要遗传物质", "1953年Watson和Crick提出DNA双螺旋结构模型", "阐明DNA如何储存和复制遗传信息", "将遗传学与生物化学统一起来，催生分子生物学", "为基因克隆、基因工程等现代生物技术奠定基础"], "check": null, "cards": [{"front": "Hershey-Chase噬菌体实验（1952年）的原理和结果是什么？", "back": "用32P标记DNA、35S标记蛋白质，追踪感染后放射性去向。结果32P进入细菌并传递给子代噬菌体，35S留在菌体外。证明DNA是主要的遗传物质。", "mnemonic": "磷标DNA进菌体，硫标蛋白留外面", "useImg": false}]}, {"i": 11, "sec": "发展历程(三)——生物化学与DNA的发现", "title": "DNA发现历程的总结与诺贝尔奖(p40)", "notes": "从1928年Griffith发现转化现象，到1944年Avery等证明DNA是转化因子，再到1952年Hershey-Chase实验利用32P和35S标记证明DNA是主要遗传物质，历经二十余年。这些工作最终获得1969年诺贝尔生理学或医学奖。这一历程不仅确立了DNA的遗传物质地位，也展示了科学假说不断被验证和修正的过程，为分子生物学的诞生奠定了坚实基础。", "page": 40, "level": "掌握", "img": "assets/img/ch01/p040.jpg", "anim": null, "fig": null, "points": ["1928年Griffith发现转化现象", "1944年Avery等证明DNA是转化因子", "1952年Hershey-Chase实验利用32P和35S标记证明DNA是主要遗传物质", "历经二十余年，最终获1969年诺贝尔生理学或医学奖", "确立DNA的遗传物质地位，展示科学假说不断被验证和修正的过程"], "check": null, "cards": [{"front": "DNA发现历程的总结：从Griffith到Hershey-Chase，最终获得什么奖？", "back": "从1928年Griffith发现转化现象，到1944年Avery等证明DNA是转化因子，再到1952年Hershey-Chase实验证明DNA是主要遗传物质，历经二十余年，最终获得1969年诺贝尔生理学或医学奖。", "mnemonic": "二八转化四四因，五二噬菌定DNA，六九诺奖终加冕", "useImg": false}]}], "mcq": [{"id": "ch01_mcq_16", "mod": "模块四：发展历程(三)——生物化学与DNA的发现", "modI": 3, "q": "1944年，Avery、McCarty和MacLeod通过肺炎链球菌转化实验证明了什么？", "o": ["A. 蛋白质是遗传物质", "B. DNA是转化因子", "C. RNA是遗传物质", "D. 多糖是遗传物质"], "a": "B", "e": "Avery等人将S型菌的各种物质分开，单独观察转化活性，发现只有DNA能引起转化，从而证明DNA是转化因子。", "kp": "ch01_s3_6"}, {"id": "ch01_mcq_17", "mod": "模块四：发展历程(三)——生物化学与DNA的发现", "modI": 3, "q": "Hershey-Chase实验中，用于标记噬菌体DNA和蛋白质的放射性同位素分别是？", "o": ["A. 32P和35S", "B. 35S和32P", "C. 14C和3H", "D. 32P和14C"], "a": "A", "e": "Hershey和Chase用32P标记DNA，用35S标记蛋白质，通过追踪放射性证明DNA进入细菌并传递给子代。", "kp": "ch01_s3_8"}, {"id": "ch01_mcq_18", "mod": "模块四：发展历程(三)——生物化学与DNA的发现", "modI": 3, "q": "“一个基因一个酶”假说由谁提出？", "o": ["A. Beadle和Tatum", "B. Watson和Crick", "C. Avery和McCarty", "D. Hershey和Chase"], "a": "A", "e": "1941年，George Beadle和Edward Tatum提出“一个基因一个酶”假说，说明基因通过控制酶的合成发挥生化作用。", "kp": "ch01_s3_3"}, {"id": "ch01_mcq_19", "mod": "模块四：发展历程(三)——生物化学与DNA的发现", "modI": 3, "q": "Griffith在1928年发现的肺炎链球菌转化现象说明？", "o": ["A. 蛋白质是遗传物质", "B. 遗传信息可以在细菌之间传递", "C. DNA是双螺旋结构", "D. 基因是DNA片段"], "a": "B", "e": "Griffith发现加热杀死的S型菌可使R型活菌转化为S型菌，表明遗传信息以某种化学形式在细菌间传递。", "kp": "ch01_s3_4"}, {"id": "ch01_mcq_20", "mod": "模块四：发展历程(三)——生物化学与DNA的发现", "modI": 3, "q": "下列哪项不是19世纪末至20世纪中期生物化学快速发展的成果？", "o": ["A. 20种基本氨基酸被揭示", "B. 肽键被证实", "C. DNA双螺旋结构被提出", "D. 三羧酸循环被发现"], "a": "C", "e": "DNA双螺旋结构由Watson和Crick于1953年提出，不属于19世纪末至20世纪中期的生物化学早期成果。", "kp": "ch01_s3_0"}], "judge": [{"id": "ch01_judge_8", "modI": 3, "q": "转化现象属于垂直遗传，即基因从父母到孩子或从母细胞到子细胞。", "a": "错", "e": "转化是遗传物质在两个完全不相关的陌生个体间传递，属于水平基因交换；垂直遗传是基因从父母到孩子或从母细胞到子细胞。", "kp": "ch01_s3_5"}, {"id": "ch01_judge_9", "modI": 3, "q": "Avery等发现只有DNA能引起转化，DNA酶可使其失活，从而证明DNA是遗传物质。", "a": "对", "e": "1944年Avery、McCarty和MacLeod证明DNA是转化因子，即遗传物质。", "kp": "ch01_s3_6"}, {"id": "ch01_judge_10", "modI": 3, "q": "“一个基因一个酶”假说由Beadle和Tatum提出，后来被修正为“一个基因一条多肽链”。", "a": "对", "e": "1941年George Beadle和Edward Tatum提出“一个基因一个酶”假说，后来这一概念被修正为“一个基因一条多肽链”。", "kp": "ch01_s3_3"}], "fill": [{"id": "ch01_fill_9", "modI": 3, "q": "1944年，Avery、McCarty和MacLeod证明________是转化因子，即遗传物质。", "a": "DNA", "kp": "ch01_s3_6"}, {"id": "ch01_fill_10", "modI": 3, "q": "1941年，Beadle和Tatum提出“一个基因一个________”假说，后修正为“一个基因一条________”。", "a": "酶,多肽链", "kp": "ch01_s3_3"}], "short": [{"id": "ch01_short_5", "modI": 3, "q": "简述Avery等证明DNA是转化因子的实验思路与意义。", "a": "1. 在Griffith实验基础上，系统寻找转化因子；2. 将S型菌的各种物质分开，单独观察其转化活性，确定唯一变量；3. 结果发现只有DNA能引起转化；4. 蛋白酶、RNA酶等不能破坏转化活性，DNA酶则可使其失活；5. 从而证明DNA是转化因子，即遗传物质；6. 奠定“DNA是遗传物质”的理论基础。", "kps": "", "kp": "ch01_s3_6"}], "calc": [{"id": "ch01_calc_2", "modI": 3, "q": "论述从Griffith转化实验到Avery等证明DNA是遗传物质的逻辑链条及其科学意义。", "a": "1928年Griffith发现，将加热杀死的光滑型S型菌与粗糙型R型活菌混合注射小鼠，可导致小鼠死亡并分离出S型活菌，表明死菌中某种物质使R型菌转化为S型菌，即转化现象。转化是遗传物质在两个完全不相关的陌生个体间传递，属于水平基因交换，几乎不发生在哺乳动物中，但可发生在细菌中。1944年Avery、McCarty和MacLeod在Griffith实验基础上，将S型菌的各种物质分开，单独观察其转化活性，确定唯一变量；结果只有DNA能引起转化，蛋白酶、RNA酶等不能破坏转化活性，DNA酶则可使其失活，从而证明DNA是转化因子，即遗传物质。意义：奠定“DNA是遗传物质”的理论基础，推动分子生物学诞生。", "steps": "1. Griffith实验现象与结论；2. 转化的定义与特点；3. Avery实验设计思路；4. 关键结果；5. 结论；6. 科学意义。", "kp": "ch01_s3_6"}], "term": [{"id": "ch01_term_11", "modI": 3, "term": "Transformation", "def": "转化：遗传物质在两个完全不相关的陌生个体间传递，属于水平基因交换；几乎不发生在哺乳动物中，但可发生在细菌中；1928年Griffith肺炎链球菌实验首次揭示；1944年Avery等证明DNA是转化因子。", "kps": "", "kp": "ch01_s3_1"}, {"id": "ch01_term_12", "modI": 3, "term": "One Gene-One Enzyme Hypothesis", "def": "一个基因一个酶假说：1941年George Beadle和Edward Tatum提出；认为基因的生化作用本质是控制酶的合成；获1958年诺贝尔生理学或医学奖；后来修正为“一个基因一条多肽链”；将基因与蛋白质功能直接联系起来。", "kps": "", "kp": "ch01_s3_1"}]}, {"i": 4, "name": "模块五：发展历程(四)——DNA双螺旋与中心法则", "slides": [{"i": 0, "sec": "发展历程(四)——DNA双螺旋与中心法则", "title": "DNA双螺旋结构的X射线晶体学证据(p41)", "notes": "20世纪50年代初，伦敦国王学院的Rosalind Franklin利用X射线晶体衍射技术研究DNA纤维，获得了著名的“51号照片”，清晰显示DNA呈螺旋状，并提示其由两条（或三条）多核苷酸链组成。她的数据成为揭示DNA三维结构的关键实验依据。Franklin于1958年英年早逝，未能分享1962年诺贝尔奖，这段历史也引发了对科学界性别与贡献认定问题的长期反思。", "page": 41, "level": "理解", "img": "assets/img/ch01/p041.jpg", "anim": null, "fig": "若展示51号照片，注意其中心X形衍射图案和层线间距，这些特征提示DNA为螺旋结构；通过衍射点的对称性和间距可推断螺旋参数和链数。", "points": ["Rosalind Franklin利用X射线晶体衍射技术研究DNA纤维，获得“51号照片”。", "51号照片清晰显示DNA呈螺旋状，并提示由两条（或三条）多核苷酸链组成。", "该数据成为揭示DNA三维结构的关键实验依据。", "Franklin于1958年去世，未能分享1962年诺贝尔奖，引发对科学界性别与贡献认定的反思。"], "check": null, "cards": [{"front": "谁拍摄了著名的DNA X射线衍射“51号照片”？", "back": "Rosalind Franklin（伦敦国王学院），照片清晰显示DNA呈螺旋状，提示由两条（或三条）多核苷酸链组成。", "mnemonic": "富兰克林拍51，螺旋真相藏其中", "useImg": false}]}, {"i": 1, "sec": "发展历程(四)——DNA双螺旋与中心法则", "title": "Chargaff规则：碱基组成的定量规律(p42)", "notes": "Erwin Chargaff在1948—1950年间通过化学分析发现，不同生物DNA中腺嘌呤(A)与胸腺嘧啶(T)的摩尔含量近似相等，鸟嘌呤(G)与胞嘧啶(C)也近似相等，即A=T、G=C，由此推出A+G=T+C（嘌呤总数等于嘧啶总数），但A+T与G+C的比值因物种而异。这一规则为碱基互补配对提供了重要化学线索，直接支持了DNA双螺旋模型中A-T、G-C的配对方式。", "page": 42, "level": "掌握", "img": "assets/img/ch01/p042.jpg", "anim": null, "fig": null, "points": ["Chargaff发现不同生物DNA中A与T摩尔含量近似相等，G与C近似相等，即A=T、G=C。", "由此推出A+G=T+C，即嘌呤总数等于嘧啶总数。", "A+T与G+C的比值因物种而异，不具有普遍恒定性。", "该规则为碱基互补配对提供了重要化学线索，直接支持DNA双螺旋模型中A-T、G-C的配对方式。"], "check": null, "cards": [{"front": "Chargaff规则的内容是什么？", "back": "A=T、G=C，故A+G=T+C（嘌呤总数=嘧啶总数）；但A+T与G+C的比值因物种而异。", "mnemonic": "A配T，G配C，嘌呤嘧啶总数齐", "useImg": false}]}, {"i": 2, "sec": "发展历程(四)——DNA双螺旋与中心法则", "title": "分子生物学的诞生：Watson与Crick提出DNA双螺旋(p43)", "notes": "1953年，James Watson与Francis Crick在综合X射线衍射数据、Chargaff规则和化学键理论的基础上，在《自然》杂志发表论文，提出DNA的双螺旋三维结构模型。该模型阐明两条反向平行的多核苷酸链围绕共同轴盘旋，碱基位于内侧并通过氢键互补配对，磷酸-脱氧核糖骨架位于外侧。这一发现标志着分子生物学的诞生，为理解遗传信息的储存、复制和传递奠定了结构基础。", "page": 43, "level": "掌握", "img": "assets/img/ch01/p043.jpg", "anim": null, "fig": "若展示DNA双螺旋示意图，注意两条链反向平行、右手螺旋；碱基对位于内部，A-T和G-C通过氢键连接；磷酸-脱氧核糖骨架位于外侧。", "points": ["1953年Watson与Crick在《自然》发表论文，提出DNA双螺旋三维结构模型。", "模型阐明两条反向平行的多核苷酸链围绕共同轴盘旋。", "碱基位于内侧并通过氢键互补配对，磷酸-脱氧核糖骨架位于外侧。", "该发现标志着分子生物学的诞生，为理解遗传信息的储存、复制和传递奠定结构基础。"], "check": null, "cards": [{"front": "Chargaff规则对DNA双螺旋模型有何意义？", "back": "为碱基互补配对提供化学线索，直接支持A-T、G-C的配对方式。", "mnemonic": "定量规律指方向，互补配对有依据", "useImg": false}]}, {"i": 3, "sec": "发展历程(四)——DNA双螺旋与中心法则", "title": "DNA双螺旋模型的科学共同体与诺贝尔奖(p44)", "notes": "DNA双螺旋模型由Watson和Crick于1953年提出，其建立离不开Maurice Wilkins及Rosalind Franklin等提供的X射线衍射数据。Watson当时34岁，Crick和Wilkins均为46岁。1962年，Watson、Crick与Wilkins共同获得诺贝尔生理学或医学奖。Wilkins任职于伦敦国王学院John Randall实验室，该实验室的晶体学工作为模型提供了关键证据。该案例体现了现代科学合作与竞争并存的复杂生态。", "page": 44, "level": "了解", "img": "assets/img/ch01/p044.jpg", "anim": null, "fig": null, "points": ["DNA双螺旋模型由Watson和Crick于1953年提出，依赖Wilkins及Franklin等提供的X射线衍射数据。", "Watson当时34岁，Crick和Wilkins均为46岁。", "1962年Watson、Crick与Wilkins共同获得诺贝尔生理学或医学奖。", "Wilkins任职于伦敦国王学院John Randall实验室，该实验室的晶体学工作为模型提供关键证据。"], "check": null, "cards": [{"front": "DNA双螺旋模型由谁于何时提出？其核心结构特征是什么？", "back": "1953年Watson与Crick提出；两条反向平行链绕共同轴盘旋，碱基在内侧氢键互补配对，磷酸-脱氧核糖骨架在外侧。", "mnemonic": "双链反向绕轴转，碱基在内骨架外", "useImg": false}]}, {"i": 4, "sec": "发展历程(四)——DNA双螺旋与中心法则", "title": "Rosalind Franklin：被忽视的关键贡献者(p45)", "notes": "Rosalind Franklin(1920—1958)拍摄的DNA X射线衍射照片，尤其是“51号照片”，为Watson和Crick确定DNA螺旋结构提供了决定性证据。然而她的贡献在早期叙述中常被淡化，且因1958年去世未能获得诺贝尔奖。完整讲述DNA双螺旋发现史，必须包括Franklin的悲剧命运与科学贡献，这既是对历史事实的尊重，也提醒人们关注科学评价中的公平与性别问题。", "page": 45, "level": "理解", "img": "assets/img/ch01/p045.jpg", "anim": null, "fig": null, "points": ["Rosalind Franklin（1920—1958）拍摄的DNA X射线衍射照片，尤其是“51号照片”，为确定DNA螺旋结构提供了决定性证据。", "她的贡献在早期叙述中常被淡化。", "因1958年去世，未能获得诺贝尔奖。", "完整讲述DNA双螺旋发现史必须包括Franklin的贡献，提醒关注科学评价中的公平与性别问题。"], "check": null, "cards": [{"front": "DNA双螺旋发现为何被视为分子生物学的诞生标志？", "back": "它阐明了遗传信息储存、复制和传递的结构基础，使研究进入分子水平。", "mnemonic": "结构一明，分子生物学诞生", "useImg": false}]}, {"i": 5, "sec": "发展历程(四)——DNA双螺旋与中心法则", "title": "从结构到功能：中心法则相关的重要发现(p47)", "notes": "在DNA双螺旋结构确立后，分子生物学迅速向功能层面拓展：信使RNA(mRNA)的发现阐明了遗传信息从DNA到蛋白质的中间载体；遗传密码的破译揭示了核苷酸序列与氨基酸序列的对应关系；操纵子模型则阐明了原核生物基因表达调控的机制。这些里程碑式发现共同开辟了分子生物学的新天地，使人们能够在分子水平上理解遗传信息的传递与调控。", "page": 47, "level": "理解", "img": "assets/img/ch01/p047.jpg", "anim": null, "fig": null, "points": ["DNA双螺旋结构确立后，分子生物学迅速向功能层面拓展。", "信使RNA（mRNA）的发现阐明了遗传信息从DNA到蛋白质的中间载体。", "遗传密码的破译揭示了核苷酸序列与氨基酸序列的对应关系。", "操纵子模型阐明了原核生物基因表达调控的机制。", "这些发现使人们能够在分子水平上理解遗传信息的传递与调控。"], "check": null, "cards": [{"front": "1962年诺贝尔生理学或医学奖授予了哪些人？Franklin为何未获奖？", "back": "Watson、Crick与Wilkins获奖；Franklin因1958年去世未能分享，其贡献早期常被淡化。", "mnemonic": "三人获奖，富兰克林早逝遗憾", "useImg": false}]}, {"i": 6, "sec": "发展历程(四)——DNA双螺旋与中心法则", "title": "科学与技术互动：分子生物学走向干涉性与创造性(p48)", "notes": "科学为技术发明提供理论依据，技术又为科学发现提供方法手段。DNA克隆技术、基因定点诱变技术、PCR扩增技术以及细胞与组织培养技术等的出现，使分子生物学从早期以“观察性”和“验证性”为主的研究，发展为能够主动“干涉性”和“创造性”地改造生物遗传物质的科学。这一转变极大推动了基因工程、医学和农业等领域的应用。", "page": 48, "level": "理解", "img": "assets/img/ch01/p048.jpg", "anim": null, "fig": null, "points": ["科学为技术发明提供理论依据，技术又为科学发现提供方法手段。", "DNA克隆、基因定点诱变、PCR扩增以及细胞与组织培养等技术的出现。", "使分子生物学从早期以“观察性”和“验证性”为主的研究，发展为能够主动“干涉性”和“创造性”地改造生物遗传物质的科学。", "这一转变极大推动了基因工程、医学和农业等领域的应用。"], "check": null, "cards": [{"front": "DNA双螺旋确立后，中心法则相关的三个重要发现是什么？", "back": "mRNA发现（DNA到蛋白质的中间载体）、遗传密码破译（核苷酸与氨基酸对应）、操纵子模型（原核基因表达调控）。", "mnemonic": "信使、密码、操纵子，功能拓展三基石", "useImg": false}]}, {"i": 7, "sec": "分子生物学研究的基本原则", "title": "Crick的中心法则与序列假说(p49)", "notes": "1957年，Crick在英国实验生物学学会演讲中首次系统论述了“中心法则”和“序列假说”。序列假说认为，核酸携带的遗传信息由其碱基序列决定；对于蛋白质编码基因，核酸的碱基序列决定蛋白质的氨基酸序列。中心法则指出，序列信息一旦从核酸传递到蛋白质，就不能再以蛋白质为模板传回核酸。该原则奠定了分子生物学信息流向的基本框架，后续补充了RNA逆转录和RNA复制等例外。", "page": 49, "level": "掌握", "img": "assets/img/ch01/p049.jpg", "anim": null, "fig": null, "points": ["1957年Crick在英国实验生物学学会演讲中首次系统论述“中心法则”和“序列假说”。", "序列假说认为核酸携带的遗传信息由其碱基序列决定；对于蛋白质编码基因，核酸的碱基序列决定蛋白质的氨基酸序列。", "中心法则指出，序列信息一旦从核酸传递到蛋白质，就不能再以蛋白质为模板传回核酸。", "该原则奠定了分子生物学信息流向的基本框架，后续补充了RNA逆转录和RNA复制等例外。"], "check": null, "cards": [{"front": "Crick的中心法则和序列假说分别是什么？", "back": "序列假说：核酸碱基序列决定蛋白质氨基酸序列；中心法则：序列信息从核酸传到蛋白质后，不能再以蛋白质为模板传回核酸。", "mnemonic": "序列决定氨基酸，信息单向不回头", "useImg": false}]}, {"i": 8, "sec": "分子生物学研究的基本原则", "title": "生物大分子的共同语言与中心法则(p50)", "notes": "构成生物大分子的单体具有高度一致性：核酸都由核苷酸组成，蛋白质都由氨基酸组成，因此所有生物共享“核酸语言”和“蛋白质语言”。遗传信息的表达遵循相同的中心法则：DNA→RNA→多肽链→蛋白质，再通过折叠形成高级结构并体现生物功能。同时，生物大分子单体的排列顺序（核苷酸序列、氨基酸序列）遵循序列假说，决定了分子的结构与功能，而生物大分子之间的相互作用也是生命活动的重要基础。", "page": 50, "level": "掌握", "img": "assets/img/ch01/p050.jpg", "anim": null, "fig": null, "points": ["构成生物大分子的单体具有高度一致性：核酸都由核苷酸组成，蛋白质都由氨基酸组成，因此所有生物共享“核酸语言”和“蛋白质语言”。", "遗传信息的表达遵循相同的中心法则：DNA→RNA→多肽链→蛋白质，再通过折叠形成高级结构并体现生物功能。", "生物大分子单体的排列顺序（核苷酸序列、氨基酸序列）遵循序列假说，决定了分子的结构与功能。", "生物大分子之间的相互作用也是生命活动的重要基础。"], "check": null, "cards": [{"front": "生物大分子的“共同语言”指什么？遗传信息表达遵循什么路径？", "back": "核酸都由核苷酸组成、蛋白质都由氨基酸组成，所有生物共享核酸语言和蛋白质语言；表达路径：DNA→RNA→多肽链→蛋白质→折叠成高级结构体现功能。", "mnemonic": "核苷酸加氨基酸，DNA到RNA再到蛋白", "useImg": false}]}], "mcq": [{"id": "ch01_mcq_21", "mod": "模块五：发展历程(四)——DNA双螺旋与中心法则", "modI": 4, "q": "Chargaff规则中，下列哪一项关系是正确的？", "o": ["A. A=T，G=C，A+G=T+C", "B. A=G，T=C，A+T=G+C", "C. A=C，T=G，A+T=G+C", "D. A=T，G=C，A+T=G+C"], "a": "A", "e": "Chargaff规则指出：A与T含量近似相等，G与C含量近似相等，因此嘌呤总数(A+G)等于嘧啶总数(T+C)，但A+T与G+C的比值因物种而异，并不一定相等。", "kp": "ch01_s4_1"}, {"id": "ch01_mcq_22", "mod": "模块五：发展历程(四)——DNA双螺旋与中心法则", "modI": 4, "q": "关于DNA双螺旋结构模型的提出，下列说法正确的是：", "o": ["A. 由Watson和Crick于1953年提出，并直接获得1962年诺贝尔生理学或医学奖", "B. 由Franklin独立提出，Watson和Crick仅进行验证", "C. 由Watson、Crick和Wilkins于1962年共同提出", "D. 由Chargaff于1950年提出"], "a": "A", "e": "Watson和Crick于1953年提出DNA双螺旋结构模型，1962年与Wilkins共同获得诺贝尔生理学或医学奖。Franklin提供了关键X射线衍射数据，但未独立提出该模型。", "kp": "ch01_s4_3"}, {"id": "ch01_mcq_23", "mod": "模块五：发展历程(四)——DNA双螺旋与中心法则", "modI": 4, "q": "Crick提出的“中心法则”核心内容是：", "o": ["A. 遗传信息可以从蛋白质传回核酸", "B. 序列信息一旦由核酸传递到蛋白质，就不能再由蛋白质作为模板传回核酸", "C. DNA的碱基序列直接决定蛋白质的空间结构", "D. 所有生物遗传信息都只从RNA流向DNA"], "a": "B", "e": "中心法则强调遗传信息流向：DNA→RNA→蛋白质，信息一旦进入蛋白质就不能再以蛋白质为模板反向传回核酸。后来发现的逆转录和RNA复制是对该法则的补充，而非否定其基本框架。", "kp": "ch01_s4_7"}, {"id": "ch01_mcq_24", "mod": "模块五：发展历程(四)——DNA双螺旋与中心法则", "modI": 4, "q": "“序列假说”认为：", "o": ["A. 蛋白质的氨基酸序列决定核酸的碱基序列", "B. 核酸所携带的信息由其碱基序列决定，对于蛋白质编码基因，核酸碱基序列决定蛋白质氨基酸序列", "C. 所有生物大分子的单体排列都是随机的", "D. DNA双螺旋的螺距决定蛋白质功能"], "a": "B", "e": "序列假说由Crick提出，指出核酸的遗传信息储存在碱基序列中，蛋白质编码基因的碱基序列决定蛋白质的氨基酸序列，这是理解遗传信息表达的基础。", "kp": "ch01_s4_7"}, {"id": "ch01_mcq_25", "mod": "模块五：发展历程(四)——DNA双螺旋与中心法则", "modI": 4, "q": "下列哪项技术使分子生物学从“观察性”“验证性”科学发展为“干涉性”“创造性”科学？", "o": ["A. X射线晶体衍射技术", "B. DNA克隆、基因定点诱变、PCR扩增及细胞与组织培养技术", "C. 显微镜观察技术", "D. 纸层析技术"], "a": "B", "e": "DNA克隆、基因定点诱变、PCR扩增以及细胞与组织培养等技术使研究者能够主动改造和创造遗传物质，推动分子生物学从观察验证走向干涉创造，并催生了基因工程等应用领域。", "kp": "ch01_s4_6"}], "judge": [{"id": "ch01_judge_1", "modI": 4, "q": "1953年沃森和克里克提出DNA双螺旋结构，标志现代分子生物学诞生。", "a": "对", "e": "讲义明确指出1953年沃森和克里克提出DNA双螺旋结构，标志现代分子生物学诞生。", "kp": "ch01_s4_2"}], "fill": [{"id": "ch01_fill_4", "modI": 4, "q": "1953年，________和________提出DNA双螺旋结构，标志现代分子生物学诞生。", "a": "沃森,克里克", "kp": "ch01_s4_2"}], "short": [], "calc": [], "term": []}, {"i": 5, "name": "模块六：现代分子生物学的研究内容与发展", "slides": [{"i": 0, "sec": "模块六：现代分子生物学的研究内容与发展", "title": "现代分子生物学的研究内容 (p51)", "notes": "本页概括了现代分子生物学的六大研究内容：基因功能研究关注功能基因如何发挥功能；基因表达调控研究关注蛋白质发挥功能的机制、蛋白质结构与合成时序同核酸的关系；信号转导研究已发展为细胞生物学分支；DNA重组技术催生了基因工程分支；生物大分子结构与功能研究形成结构分子生物学；基因组与功能基因组的宏观分析则推动生物信息学兴起。这些方向相互交叉，构成现代分子生物学的核心框架。", "page": 51, "level": "掌握", "img": "assets/img/ch01/p051.jpg", "anim": null, "fig": null, "points": ["现代分子生物学六大研究内容：基因功能、基因表达调控、信号转导、DNA重组技术、生物大分子结构与功能、基因组与功能基因组分析。", "基因功能研究关注功能基因如何发挥功能；基因表达调控关注蛋白质功能机制、蛋白质结构与合成时序同核酸的关系。", "信号转导研究已发展为细胞生物学分支；DNA重组技术催生基因工程分支。", "生物大分子结构与功能研究形成结构分子生物学；基因组与功能基因组宏观分析推动生物信息学兴起。", "各方向相互交叉，构成现代分子生物学核心框架。"], "check": null, "cards": [{"front": "现代分子生物学的六大研究内容是什么？", "back": "基因功能研究、基因表达调控、信号转导、DNA重组技术（基因工程）、生物大分子结构与功能（结构分子生物学）、基因组与功能基因组（生物信息学）。", "mnemonic": "功调信重结组", "useImg": false}, {"front": "Maddox对分子生物学研究现状的主要批评是什么？", "back": "许多分子生物学家发表的论文不涉及完整动植物，也很少讨论生理学；实验数据可能主要由凝胶电泳图（gels）构成，过度聚焦还原性、技术性数据而忽视整体生物体和生理功能。", "mnemonic": "只见gels，不见生物体", "useImg": false}]}, {"i": 1, "sec": "模块六：现代分子生物学的研究内容与发展", "title": "现代分子生物学发展史的三大转折 (p52)", "notes": "现代分子生物学的发展经历了三大转折：研究对象的变换、研究策略的转变和研究内容的拓展。理论开拓与技术发展相互促进，共同推动现代分子生物学的形成。研究对象从早期模式生物扩展到高等真核生物乃至宏观与微观结合；研究策略从还原论走向整体论；研究内容不断向组学、系统生物学拓展。理解这三大转折有助于把握学科发展的内在逻辑。", "page": 52, "level": "理解", "img": "assets/img/ch01/p052.jpg", "anim": null, "fig": null, "points": ["现代分子生物学发展史三大转折：研究对象变换、研究策略转变、研究内容拓展。", "理论开拓与技术发展相互促进，共同推动学科形成。", "研究对象从早期模式生物扩展到高等真核生物乃至宏观与微观结合。", "研究策略从还原论走向整体论。", "研究内容不断向组学、系统生物学拓展。"], "check": null, "cards": [{"front": "现代分子生物学发展史的三大转折是什么？", "back": "研究对象的变换、研究策略的转变、研究内容的拓展。", "mnemonic": "对象换、策略转、内容拓", "useImg": false}]}, {"i": 2, "sec": "模块六：现代分子生物学的研究内容与发展", "title": "研究对象的变换：从经典模式生物到噬菌体群 (p53)", "notes": "20世纪中期，研究对象从果蝇、豌豆等经典材料转向微生物、噬菌体及其他简单模式生物。噬菌体群（phage group）的研究催生了顺反子（cistron）、“一基因一酶”假说、操纵子等新理论和新概念，使生物学开始腾飞。Delbrück、Hershey和Luria因噬菌体研究获1969年诺贝尔奖。这一转变体现了简单模式生物在揭示生命基本规律中的巨大优势。", "page": 53, "level": "理解", "img": "assets/img/ch01/p053.jpg", "anim": null, "fig": null, "points": ["20世纪中期研究对象从果蝇、豌豆等经典材料转向微生物、噬菌体及其他简单模式生物。", "噬菌体群研究催生顺反子、‘一基因一酶’假说、操纵子等新理论和新概念。", "Delbrück、Hershey和Luria因噬菌体研究获1969年诺贝尔奖。", "简单模式生物在揭示生命基本规律中具有巨大优势。"], "check": null, "cards": [{"front": "20世纪中期分子生物学研究对象发生了怎样的变换？", "back": "从果蝇、豌豆等经典材料转向微生物、噬菌体及其他简单模式生物；噬菌体群研究催生了顺反子、一基因一酶假说、操纵子等理论。", "mnemonic": "果蝇豌豆→噬菌体群", "useImg": false}]}, {"i": 3, "sec": "模块六：现代分子生物学的研究内容与发展", "title": "研究策略的转变：从还原论到整体论 (p54)", "notes": "1990年10月1日人类基因组计划（HGP）启动，标志着研究策略从20世纪的还原论（reductionism）向21世纪的整体论（holism）转变。还原论主张“化繁为简”，通过分解研究复杂生命现象；整体论则强调从全局和系统层面理解生命。HGP推动了大科学和组学时代，使生物学研究从单个基因转向全基因组、全转录组等整体分析，深刻改变了学科面貌。", "page": 54, "level": "掌握", "img": "assets/img/ch01/p054.jpg", "anim": null, "fig": null, "points": ["1990年10月1日人类基因组计划（HGP）启动，标志研究策略从还原论向整体论转变。", "还原论主张‘化繁为简’，通过分解研究复杂生命现象。", "整体论强调从全局和系统层面理解生命。", "HGP推动大科学和组学时代，使研究从单个基因转向全基因组、全转录组等整体分析。", "研究策略转变深刻改变了学科面貌。"], "check": null, "cards": [{"front": "Delbrück、Hershey和Luria因何获1969年诺贝尔奖？", "back": "因噬菌体研究（噬菌体群）获奖。", "mnemonic": "噬菌体三巨头", "useImg": false}]}, {"i": 4, "sec": "模块六：现代分子生物学的研究内容与发展", "title": "组学概念：Genome、Transcriptome与Proteome (p55)", "notes": "本页给出组学的基本构词与概念：Genome=Gene+ome，即基因组；Transcriptome=Transcript+ome，即转录组；Protein+ome=Proteome，即蛋白质组。这些“组学”概念体现了从单个分子到全局集合的研究范式转变。基因组指一个生物体全部遗传信息，转录组指特定条件下全部转录产物，蛋白质组指全部蛋白质。组学技术为系统理解生命活动提供了高通量手段。", "page": 55, "level": "掌握", "img": "assets/img/ch01/p055.jpg", "anim": null, "fig": null, "points": ["Genome=Gene+ome，即基因组；Transcriptome=Transcript+ome，即转录组；Protein+ome=Proteome，即蛋白质组。", "组学概念体现从单个分子到全局集合的研究范式转变。", "基因组指一个生物体全部遗传信息；转录组指特定条件下全部转录产物；蛋白质组指全部蛋白质。", "组学技术为系统理解生命活动提供高通量手段。"], "check": null, "cards": [{"front": "研究策略从还原论向整体论转变的标志是什么？", "back": "1990年10月1日人类基因组计划（HGP）启动。", "mnemonic": "HGP=整体论起点", "useImg": false}]}, {"i": 5, "sec": "模块六：现代分子生物学的研究内容与发展", "title": "分子生物学渗透到生命科学各领域 (p56)", "notes": "分子生物学已渗透到生物学的几乎所有领域，形成了分子结构生物学、分子发育生物学、分子神经生物学、分子育种学、分子肿瘤学、分子细胞生物学、分子免疫学、分子病毒学、分子生理学、分子考古学、分子遗传学、分子数量遗传学、分子生态学、分子进化学等众多分支。分子生物学已成为生命科学领域的带头学科，其理论和技术广泛支撑医学、农业、生态等应用领域。", "page": 56, "level": "了解", "img": "assets/img/ch01/p056.jpg", "anim": null, "fig": null, "points": ["分子生物学已渗透到生物学几乎所有领域，形成众多分支学科。", "分支包括分子结构生物学、分子发育生物学、分子神经生物学、分子育种学、分子肿瘤学、分子细胞生物学、分子免疫学、分子病毒学、分子生理学、分子考古学、分子遗传学、分子数量遗传学、分子生态学、分子进化学等。", "分子生物学已成为生命科学领域的带头学科。", "其理论和技术广泛支撑医学、农业、生态等应用领域。"], "check": null, "cards": [{"front": "还原论与整体论的核心区别是什么？", "back": "还原论主张化繁为简，通过分解研究复杂生命现象；整体论强调从全局和系统层面理解生命。", "mnemonic": "还原拆、整体看", "useImg": false}]}, {"i": 6, "sec": "模块六：现代分子生物学的研究内容与发展", "title": "反思：分子生物学是否已成为一门科学？ (p57)", "notes": "本页引用《自然》杂志主编Maddox J.于1992年发表的文章《Is molecular biology yet a science?》（Nature 1992, 355: 201）。该文对分子生物学是否已形成成熟科学体系提出反思，引发学界对分子生物学研究方法、理论整合与学科定位的讨论。这一质疑从侧面反映了分子生物学在快速发展中面临的理论统一性和方法论挑战，也促使研究者思考如何从描述性研究走向机制性、系统性科学。", "page": 57, "level": "了解", "img": "assets/img/ch01/p057.jpg", "anim": null, "fig": null, "points": ["引用《自然》杂志主编Maddox J.于1992年发表的文章《Is molecular biology yet a science?》（Nature 1992, 355: 201）。", "该文对分子生物学是否已形成成熟科学体系提出反思。", "引发学界对分子生物学研究方法、理论整合与学科定位的讨论。", "质疑从侧面反映分子生物学快速发展中面临的理论统一性和方法论挑战。", "促使研究者思考如何从描述性研究走向机制性研究。"], "check": null, "cards": [{"front": "Genome、Transcriptome、Proteome分别由什么词构成？含义是什么？", "back": "Genome=Gene+ome（基因组，全部遗传信息）；Transcriptome=Transcript+ome（转录组，特定条件下全部转录产物）；Proteome=Protein+ome（蛋白质组，全部蛋白质）。", "mnemonic": "基因+ome、转录+ome、蛋白+ome", "useImg": false}]}, {"i": 7, "sec": "模块六：现代分子生物学的研究内容与发展", "title": "Maddox对分子生物学研究现状的批评 (p58)", "notes": "本页继续引用Maddox的观点：如今有大批被称为分子生物学家的人，其发表的论文不涉及完整动植物，也很少讨论生理学；对这些人而言，实验数据可能主要由业内所称的“gels”（凝胶电泳图）构成。这一批评指出分子生物学研究可能过度聚焦于还原性、技术性数据，而忽视整体生物体和生理功能。它提醒我们，分子生物学需与生理学、细胞生物学和整体生物学结合，才能全面理解生命现象。", "page": 58, "level": "了解", "img": "assets/img/ch01/p058.jpg", "anim": null, "fig": null, "points": ["Maddox批评：大批分子生物学家发表的论文不涉及完整动植物，也很少讨论生理学。", "对这些人而言，实验数据可能主要由业内所称的‘gels’（凝胶电泳图）构成。", "批评指出分子生物学研究可能过度聚焦于还原性、技术性数据，而忽视整体生物体和生理功能。", "提醒分子生物学需与生理学、细胞生物学和整体生物学结合，才能全面理解生命现象。"], "check": null, "cards": [{"front": "Maddox 1992年在《自然》发表的文章标题是什么？其核心质疑是什么？", "back": "标题为《Is molecular biology yet a science?》（Nature 1992, 355: 201）；质疑分子生物学是否已形成成熟科学体系，反映其理论统一性与方法论挑战。", "mnemonic": "分子生物学算科学吗？", "useImg": false}]}], "mcq": [{"id": "ch01_mcq_26", "mod": "模块六：现代分子生物学的研究内容与发展", "modI": 5, "q": "下列哪项不属于现代分子生物学的主要研究内容？", "o": ["A. 基因功能研究", "B. 基因表达调控研究", "C. 生物大分子的结构功能研究", "D. 天体物理学研究"], "a": "D", "e": "现代分子生物学的研究内容包括基因功能、基因表达调控、信号转导、DNA重组技术、生物大分子结构与功能、基因组与功能基因组等，天体物理学不属于其研究内容。", "kp": "ch01_s5_0"}, {"id": "ch01_mcq_27", "mod": "模块六：现代分子生物学的研究内容与发展", "modI": 5, "q": "现代分子生物学发展史的三大转折不包括下列哪一项？", "o": ["A. 研究对象的变换", "B. 研究策略的转变", "C. 研究内容的拓展", "D. 研究经费的减少"], "a": "D", "e": "现代分子生物学发展史的三大转折是研究对象的变换、研究策略的转变和研究内容的拓展，研究经费减少不属于学科发展的转折。", "kp": "ch01_s5_1"}, {"id": "ch01_mcq_28", "mod": "模块六：现代分子生物学的研究内容与发展", "modI": 5, "q": "20世纪中期，噬菌体群（phage group）研究催生了下列哪一理论或概念？", "o": ["A. 相对论", "B. 操纵子模型", "C. 板块构造学说", "D. 量子力学"], "a": "B", "e": "噬菌体群研究催生了顺反子、一基因一酶假说、操纵子等新理论和新概念，Delbrück、Hershey和Luria因此获得1969年诺贝尔奖。", "kp": "ch01_s5_2"}, {"id": "ch01_mcq_29", "mod": "模块六：现代分子生物学的研究内容与发展", "modI": 5, "q": "1990年10月1日启动的人类基因组计划（HGP）标志着研究策略发生了怎样的转变？", "o": ["A. 从整体论转向还原论", "B. 从还原论转向整体论", "C. 从微观转向宏观", "D. 从宏观转向微观"], "a": "B", "e": "HGP的启动标志着研究策略从20世纪的还原论（化繁为简）向21世纪的整体论转变，推动了大科学和组学时代。", "kp": "ch01_s5_3"}, {"id": "ch01_mcq_30", "mod": "模块六：现代分子生物学的研究内容与发展", "modI": 5, "q": "下列组学概念对应关系正确的是？", "o": ["A. Genome=Gene+ome，即蛋白质组", "B. Transcriptome=Transcript+ome，即转录组", "C. Proteome=Protein+ome，即基因组", "D. Genome=Gene+ome，即转录组"], "a": "B", "e": "Genome=Gene+ome，即基因组；Transcriptome=Transcript+ome，即转录组；Proteome=Protein+ome，即蛋白质组。因此B项正确。", "kp": "ch01_s5_4"}], "judge": [], "fill": [], "short": [], "calc": [], "term": []}], "mcq": [{"id": "ch01_mcq_1", "mod": "模块一：分子生物学与21世纪生命科学", "modI": 0, "q": "标志着现代分子生物学诞生的里程碑事件是（　）。", "o": ["A. 1859年《物种起源》发表", "B. 1865年《植物杂交实验》发表", "C. 1953年DNA双螺旋结构模型提出", "D. 2000年人类基因组工作草图完成"], "a": "C", "e": "1953年沃森和克里克提出DNA双螺旋结构模型，并随后促成中心法则的建立，被视为现代分子生物学诞生的标志。A、B是遗传学与进化论的重要基础，D是基因组学时代的里程碑。", "kp": "ch01_s0_0"}, {"id": "ch01_mcq_2", "mod": "模块一：分子生物学与21世纪生命科学", "modI": 0, "q": "根据PPT数据，在《Nature》《Science》等权威刊物中，生命科学类论文所占比例约为（　）。", "o": ["A. 35%", "B. 45%", "C. 53%", "D. 56%"], "a": "D", "e": "PPT指出，当今学术论文中生命科学类占53%，而在《Nature》《Science》等权威刊物中达到56%。因此选D。", "kp": "ch01_s0_1"}, {"id": "ch01_mcq_3", "mod": "模块一：分子生物学与21世纪生命科学", "modI": 0, "q": "下列哪项技术被称为可编程基因编辑技术，并在人类基因组工作草图完成之后建立？（　）", "o": ["A. PCR技术", "B. CRISPR-Cas9", "C. 桑格测序法", "D. 基因重组技术"], "a": "B", "e": "CRISPR-Cas9是一种可编程的基因编辑技术，能够对基因组进行精准修饰，是继人类基因组计划之后分子生物学领域的重大突破。PCR、桑格测序和基因重组技术均早于或不属于可编程基因编辑范畴。", "kp": "ch01_s0_0"}, {"id": "ch01_mcq_4", "mod": "模块一：分子生物学与21世纪生命科学", "modI": 0, "q": "PPT从多个层面说明生命科学受到高度关注，下列哪项不属于其列举的层面？（　）", "o": ["A. 各国政府高度关注生命科学前沿学科", "B. 企业家投巨资发展生物技术", "C. 新闻媒体聚焦生物技术成果", "D. 各国政府限制分子生物学课程设置"], "a": "D", "e": "PPT列举的层面包括政府关注、科学家抢占制高点、企业家投资、媒体聚焦、民众关心以及高校将分子生物学列为学位课程。D项“限制分子生物学课程设置”与原文相反，不属于列举内容。", "kp": "ch01_s0_2"}, {"id": "ch01_mcq_5", "mod": "模块一：分子生物学与21世纪生命科学", "modI": 0, "q": "现代分子生物学的核心理论框架主要包括（　）。", "o": ["A. 细胞学说和进化论", "B. DNA双螺旋结构模型和中心法则", "C. 孟德尔遗传定律和染色体学说", "D. 自然选择学说和基因漂变理论"], "a": "B", "e": "PPT明确指出，以DNA双螺旋结构模型和“中心法则”为核心的现代分子生物学引发了各种事件、决策和观念的更新。因此B项正确。", "kp": "ch01_s0_0"}, {"id": "ch01_mcq_6", "mod": "模块二：发展历程(一)——进化论与细胞学说", "modI": 1, "q": "达尔文随贝格尔号军舰环球考察的时间是？", "o": ["A. 1825—1827年", "B. 1828—1831年", "C. 1831—1836年", "D. 1859—1882年"], "a": "C", "e": "达尔文于1831—1836年随贝格尔号军舰进行环球考察，为其进化论思想积累了大量证据。", "kp": "ch01_s1_0"}, {"id": "ch01_mcq_7", "mod": "模块二：发展历程(一)——进化论与细胞学说", "modI": 1, "q": "首次提出“cell”一词的科学家是？", "o": ["A. 列文虎克", "B. 罗伯特·胡克", "C. 施莱登", "D. 施旺"], "a": "B", "e": "1665年罗伯特·胡克在《显微图谱》中首次使用“cell”一词描述软木薄片中的小室。", "kp": "ch01_s1_5"}, {"id": "ch01_mcq_8", "mod": "模块二：发展历程(一)——进化论与细胞学说", "modI": 1, "q": "细胞学说的主要建立者是？", "o": ["A. 达尔文和胡克", "B. 列文虎克和胡克", "C. 施莱登和施旺", "D. 达尔文和施旺"], "a": "C", "e": "1838—1839年，施莱登和施旺分别研究植物和动物，共同提出细胞学说。", "kp": "ch01_s1_6"}, {"id": "ch01_mcq_9", "mod": "模块二：发展历程(一)——进化论与细胞学说", "modI": 1, "q": "细胞学说的核心内容不包括？", "o": ["A. 植物和动物都由细胞组成", "B. 细胞是生物体结构和功能的基本单位", "C. 细胞只能由已存在的细胞产生", "D. 细胞是生命活动的基本单位"], "a": "C", "e": "“细胞只能由已存在的细胞产生”是后来魏尔肖对细胞学说的补充，不属于施莱登和施旺最初提出的核心内容。", "kp": "ch01_s1_6"}, {"id": "ch01_mcq_10", "mod": "模块二：发展历程(一)——进化论与细胞学说", "modI": 1, "q": "达尔文进化论的核心思想可概括为？", "o": ["A. 上帝创造万物", "B. 物竞天择，适者生存", "C. 细胞是生命的基本单位", "D. 获得性遗传"], "a": "B", "e": "达尔文进化论以自然选择为核心，常概括为“物竞天择，适者生存”，从根基上动摇了“创世说”。", "kp": "ch01_s1_1"}, {"id": "ch01_mcq_11", "mod": "模块三：发展历程(二)——遗传学与染色体理论", "modI": 2, "q": "孟德尔于哪一年发表《植物杂交实验的遗传学定理》？", "o": ["A. 1859年", "B. 1865年", "C. 1900年", "D. 1910年"], "a": "B", "e": "孟德尔于1865年发表《植物杂交实验的遗传学定理》，提出孟德尔定律。1900年三位科学家重新发现该定律，遗传学正式诞生。", "kp": "ch01_s2_0"}, {"id": "ch01_mcq_12", "mod": "模块三：发展历程(二)——遗传学与染色体理论", "modI": 2, "q": "孟德尔第一定律（分离定律）中，子二代显性与隐性表型的比值是？", "o": ["A. 1:1", "B. 2:1", "C. 3:1", "D. 9:3:3:1"], "a": "C", "e": "孟德尔发现子二代中显性表型与隐性表型的比值为3:1，据此提出分离定律。9:3:3:1是两对性状自由组合的典型比例。", "kp": "ch01_s2_2"}, {"id": "ch01_mcq_13", "mod": "模块三：发展历程(二)——遗传学与染色体理论", "modI": 2, "q": "1909年提出“gene”一词描述孟德尔“遗传因子”概念的科学家是？", "o": ["A. 摩尔根", "B. 约翰森", "C. 弗莱明", "D. 德弗里斯"], "a": "B", "e": "1909年丹麦植物学家约翰森用“gene”一词描述孟德尔的“遗传因子”概念，并区分了基因型与表型。", "kp": "ch01_s2_7"}, {"id": "ch01_mcq_14", "mod": "模块三：发展历程(二)——遗传学与染色体理论", "modI": 2, "q": "摩尔根通过果蝇实验证明基因位于染色体上，他获得诺贝尔奖的理由是？", "o": ["A. 发现DNA双螺旋结构", "B. 发现染色体在遗传中的作用", "C. 发现转座子", "D. 提出中心法则"], "a": "B", "e": "摩尔根因“发现染色体在遗传中的作用”获得诺贝尔奖，他通过果蝇实验证明基因位于染色体上，为遗传的染色体理论提供直接证据。", "kp": "ch01_s2_9"}, {"id": "ch01_mcq_15", "mod": "模块三：发展历程(二)——遗传学与染色体理论", "modI": 2, "q": "关于摩尔根的基因论，下列哪项不正确？", "o": ["A. 基因呈线状排列在染色体上", "B. 基因是功能单位、突变单位和重组单位", "C. 基因不可突变", "D. 基因可交换"], "a": "C", "e": "摩尔根基因论认为基因可突变、可交换，是功能单位、突变单位和重组单位三位一体。选项C“基因不可突变”与基因论相悖。", "kp": "ch01_s2_13"}, {"id": "ch01_mcq_16", "mod": "模块四：发展历程(三)——生物化学与DNA的发现", "modI": 3, "q": "1944年，Avery、McCarty和MacLeod通过肺炎链球菌转化实验证明了什么？", "o": ["A. 蛋白质是遗传物质", "B. DNA是转化因子", "C. RNA是遗传物质", "D. 多糖是遗传物质"], "a": "B", "e": "Avery等人将S型菌的各种物质分开，单独观察转化活性，发现只有DNA能引起转化，从而证明DNA是转化因子。", "kp": "ch01_s3_6"}, {"id": "ch01_mcq_17", "mod": "模块四：发展历程(三)——生物化学与DNA的发现", "modI": 3, "q": "Hershey-Chase实验中，用于标记噬菌体DNA和蛋白质的放射性同位素分别是？", "o": ["A. 32P和35S", "B. 35S和32P", "C. 14C和3H", "D. 32P和14C"], "a": "A", "e": "Hershey和Chase用32P标记DNA，用35S标记蛋白质，通过追踪放射性证明DNA进入细菌并传递给子代。", "kp": "ch01_s3_8"}, {"id": "ch01_mcq_18", "mod": "模块四：发展历程(三)——生物化学与DNA的发现", "modI": 3, "q": "“一个基因一个酶”假说由谁提出？", "o": ["A. Beadle和Tatum", "B. Watson和Crick", "C. Avery和McCarty", "D. Hershey和Chase"], "a": "A", "e": "1941年，George Beadle和Edward Tatum提出“一个基因一个酶”假说，说明基因通过控制酶的合成发挥生化作用。", "kp": "ch01_s3_3"}, {"id": "ch01_mcq_19", "mod": "模块四：发展历程(三)——生物化学与DNA的发现", "modI": 3, "q": "Griffith在1928年发现的肺炎链球菌转化现象说明？", "o": ["A. 蛋白质是遗传物质", "B. 遗传信息可以在细菌之间传递", "C. DNA是双螺旋结构", "D. 基因是DNA片段"], "a": "B", "e": "Griffith发现加热杀死的S型菌可使R型活菌转化为S型菌，表明遗传信息以某种化学形式在细菌间传递。", "kp": "ch01_s3_4"}, {"id": "ch01_mcq_20", "mod": "模块四：发展历程(三)——生物化学与DNA的发现", "modI": 3, "q": "下列哪项不是19世纪末至20世纪中期生物化学快速发展的成果？", "o": ["A. 20种基本氨基酸被揭示", "B. 肽键被证实", "C. DNA双螺旋结构被提出", "D. 三羧酸循环被发现"], "a": "C", "e": "DNA双螺旋结构由Watson和Crick于1953年提出，不属于19世纪末至20世纪中期的生物化学早期成果。", "kp": "ch01_s3_0"}, {"id": "ch01_mcq_21", "mod": "模块五：发展历程(四)——DNA双螺旋与中心法则", "modI": 4, "q": "Chargaff规则中，下列哪一项关系是正确的？", "o": ["A. A=T，G=C，A+G=T+C", "B. A=G，T=C，A+T=G+C", "C. A=C，T=G，A+T=G+C", "D. A=T，G=C，A+T=G+C"], "a": "A", "e": "Chargaff规则指出：A与T含量近似相等，G与C含量近似相等，因此嘌呤总数(A+G)等于嘧啶总数(T+C)，但A+T与G+C的比值因物种而异，并不一定相等。", "kp": "ch01_s4_1"}, {"id": "ch01_mcq_22", "mod": "模块五：发展历程(四)——DNA双螺旋与中心法则", "modI": 4, "q": "关于DNA双螺旋结构模型的提出，下列说法正确的是：", "o": ["A. 由Watson和Crick于1953年提出，并直接获得1962年诺贝尔生理学或医学奖", "B. 由Franklin独立提出，Watson和Crick仅进行验证", "C. 由Watson、Crick和Wilkins于1962年共同提出", "D. 由Chargaff于1950年提出"], "a": "A", "e": "Watson和Crick于1953年提出DNA双螺旋结构模型，1962年与Wilkins共同获得诺贝尔生理学或医学奖。Franklin提供了关键X射线衍射数据，但未独立提出该模型。", "kp": "ch01_s4_3"}, {"id": "ch01_mcq_23", "mod": "模块五：发展历程(四)——DNA双螺旋与中心法则", "modI": 4, "q": "Crick提出的“中心法则”核心内容是：", "o": ["A. 遗传信息可以从蛋白质传回核酸", "B. 序列信息一旦由核酸传递到蛋白质，就不能再由蛋白质作为模板传回核酸", "C. DNA的碱基序列直接决定蛋白质的空间结构", "D. 所有生物遗传信息都只从RNA流向DNA"], "a": "B", "e": "中心法则强调遗传信息流向：DNA→RNA→蛋白质，信息一旦进入蛋白质就不能再以蛋白质为模板反向传回核酸。后来发现的逆转录和RNA复制是对该法则的补充，而非否定其基本框架。", "kp": "ch01_s4_7"}, {"id": "ch01_mcq_24", "mod": "模块五：发展历程(四)——DNA双螺旋与中心法则", "modI": 4, "q": "“序列假说”认为：", "o": ["A. 蛋白质的氨基酸序列决定核酸的碱基序列", "B. 核酸所携带的信息由其碱基序列决定，对于蛋白质编码基因，核酸碱基序列决定蛋白质氨基酸序列", "C. 所有生物大分子的单体排列都是随机的", "D. DNA双螺旋的螺距决定蛋白质功能"], "a": "B", "e": "序列假说由Crick提出，指出核酸的遗传信息储存在碱基序列中，蛋白质编码基因的碱基序列决定蛋白质的氨基酸序列，这是理解遗传信息表达的基础。", "kp": "ch01_s4_7"}, {"id": "ch01_mcq_25", "mod": "模块五：发展历程(四)——DNA双螺旋与中心法则", "modI": 4, "q": "下列哪项技术使分子生物学从“观察性”“验证性”科学发展为“干涉性”“创造性”科学？", "o": ["A. X射线晶体衍射技术", "B. DNA克隆、基因定点诱变、PCR扩增及细胞与组织培养技术", "C. 显微镜观察技术", "D. 纸层析技术"], "a": "B", "e": "DNA克隆、基因定点诱变、PCR扩增以及细胞与组织培养等技术使研究者能够主动改造和创造遗传物质，推动分子生物学从观察验证走向干涉创造，并催生了基因工程等应用领域。", "kp": "ch01_s4_6"}, {"id": "ch01_mcq_26", "mod": "模块六：现代分子生物学的研究内容与发展", "modI": 5, "q": "下列哪项不属于现代分子生物学的主要研究内容？", "o": ["A. 基因功能研究", "B. 基因表达调控研究", "C. 生物大分子的结构功能研究", "D. 天体物理学研究"], "a": "D", "e": "现代分子生物学的研究内容包括基因功能、基因表达调控、信号转导、DNA重组技术、生物大分子结构与功能、基因组与功能基因组等，天体物理学不属于其研究内容。", "kp": "ch01_s5_0"}, {"id": "ch01_mcq_27", "mod": "模块六：现代分子生物学的研究内容与发展", "modI": 5, "q": "现代分子生物学发展史的三大转折不包括下列哪一项？", "o": ["A. 研究对象的变换", "B. 研究策略的转变", "C. 研究内容的拓展", "D. 研究经费的减少"], "a": "D", "e": "现代分子生物学发展史的三大转折是研究对象的变换、研究策略的转变和研究内容的拓展，研究经费减少不属于学科发展的转折。", "kp": "ch01_s5_1"}, {"id": "ch01_mcq_28", "mod": "模块六：现代分子生物学的研究内容与发展", "modI": 5, "q": "20世纪中期，噬菌体群（phage group）研究催生了下列哪一理论或概念？", "o": ["A. 相对论", "B. 操纵子模型", "C. 板块构造学说", "D. 量子力学"], "a": "B", "e": "噬菌体群研究催生了顺反子、一基因一酶假说、操纵子等新理论和新概念，Delbrück、Hershey和Luria因此获得1969年诺贝尔奖。", "kp": "ch01_s5_2"}, {"id": "ch01_mcq_29", "mod": "模块六：现代分子生物学的研究内容与发展", "modI": 5, "q": "1990年10月1日启动的人类基因组计划（HGP）标志着研究策略发生了怎样的转变？", "o": ["A. 从整体论转向还原论", "B. 从还原论转向整体论", "C. 从微观转向宏观", "D. 从宏观转向微观"], "a": "B", "e": "HGP的启动标志着研究策略从20世纪的还原论（化繁为简）向21世纪的整体论转变，推动了大科学和组学时代。", "kp": "ch01_s5_3"}, {"id": "ch01_mcq_30", "mod": "模块六：现代分子生物学的研究内容与发展", "modI": 5, "q": "下列组学概念对应关系正确的是？", "o": ["A. Genome=Gene+ome，即蛋白质组", "B. Transcriptome=Transcript+ome，即转录组", "C. Proteome=Protein+ome，即基因组", "D. Genome=Gene+ome，即转录组"], "a": "B", "e": "Genome=Gene+ome，即基因组；Transcriptome=Transcript+ome，即转录组；Proteome=Protein+ome，即蛋白质组。因此B项正确。", "kp": "ch01_s5_4"}], "judge": [{"id": "ch01_judge_1", "modI": 4, "q": "1953年沃森和克里克提出DNA双螺旋结构，标志现代分子生物学诞生。", "a": "对", "e": "讲义明确指出1953年沃森和克里克提出DNA双螺旋结构，标志现代分子生物学诞生。", "kp": "ch01_s4_2"}, {"id": "ch01_judge_2", "modI": 1, "q": "达尔文在《物种起源》中提出了以自然选择为核心的进化论。", "a": "对", "e": "1859年达尔文出版《物种起源》，提出以自然选择为核心的进化论，用“物竞天择，适者生存”解释物种起源与多样性。", "kp": "ch01_s1_1"}, {"id": "ch01_judge_3", "modI": 2, "q": "孟德尔第一定律是自由组合定律，第二定律是分离定律。", "a": "错", "e": "孟德尔第一定律是分离定律，第二定律是自由组合定律。", "kp": "ch01_s2_3"}, {"id": "ch01_judge_4", "modI": 2, "q": "孟德尔在1865年发表《植物杂交实验》，其工作当时即被科学界广泛承认。", "a": "错", "e": "孟德尔工作长期被忽视，直到1900年三位科学家分别重新发现这些定律，遗传学才正式诞生。", "kp": "ch01_s2_0"}, {"id": "ch01_judge_5", "modI": 2, "q": "1909年约翰森用“gene”一词描述孟德尔的“遗传因子”概念，并区分了基因型与表型。", "a": "对", "e": "讲义指出1909年丹麦植物学家约翰森用“gene”一词描述孟德尔的“遗传因子”概念，并区分了基因型与表型。", "kp": "ch01_s2_7"}, {"id": "ch01_judge_6", "modI": 2, "q": "摩尔根通过果蝇杂交实验证明基因位于染色体上，并获得诺贝尔奖。", "a": "对", "e": "1910年摩尔根通过果蝇杂交实验将基因与染色体联系起来，证明基因位于染色体上，获奖理由是“发现染色体在遗传中的作用”。", "kp": "ch01_s2_9"}, {"id": "ch01_judge_7", "modI": 2, "q": "同一基因座上的不同形式称为等位基因。", "a": "对", "e": "讲义指出同一基因座上的不同形式称为等位基因。", "kp": "ch01_s2_10"}, {"id": "ch01_judge_8", "modI": 3, "q": "转化现象属于垂直遗传，即基因从父母到孩子或从母细胞到子细胞。", "a": "错", "e": "转化是遗传物质在两个完全不相关的陌生个体间传递，属于水平基因交换；垂直遗传是基因从父母到孩子或从母细胞到子细胞。", "kp": "ch01_s3_5"}, {"id": "ch01_judge_9", "modI": 3, "q": "Avery等发现只有DNA能引起转化，DNA酶可使其失活，从而证明DNA是遗传物质。", "a": "对", "e": "1944年Avery、McCarty和MacLeod证明DNA是转化因子，即遗传物质。", "kp": "ch01_s3_6"}, {"id": "ch01_judge_10", "modI": 3, "q": "“一个基因一个酶”假说由Beadle和Tatum提出，后来被修正为“一个基因一条多肽链”。", "a": "对", "e": "1941年George Beadle和Edward Tatum提出“一个基因一个酶”假说，后来这一概念被修正为“一个基因一条多肽链”。", "kp": "ch01_s3_3"}], "fill": [{"id": "ch01_fill_1", "modI": 1, "q": "1859年，达尔文发表《________》，奠定进化论基础。", "a": "物种起源", "kp": "ch01_s1_1"}, {"id": "ch01_fill_2", "modI": 2, "q": "1865年，孟德尔发表《________》，揭示遗传规律。", "a": "植物杂交实验", "kp": "ch01_s2_0"}, {"id": "ch01_fill_3", "modI": 2, "q": "1910年，摩尔根通过________杂交实验将基因定位到染色体。", "a": "果蝇", "kp": "ch01_s2_9"}, {"id": "ch01_fill_4", "modI": 4, "q": "1953年，________和________提出DNA双螺旋结构，标志现代分子生物学诞生。", "a": "沃森,克里克", "kp": "ch01_s4_2"}, {"id": "ch01_fill_5", "modI": 0, "q": "2000年，________工作草图宣布完成，开启基因组学时代。", "a": "人类基因组", "kp": "ch01_s0_0"}, {"id": "ch01_fill_6", "modI": 2, "q": "孟德尔第一定律又称________，F2中显性与隐性表型之比为________。", "a": "分离定律,3:1", "kp": "ch01_s2_2"}, {"id": "ch01_fill_7", "modI": 2, "q": "孟德尔第二定律又称________，两对相对性状F2表型比接近________。", "a": "自由组合定律,9:3:3:1", "kp": "ch01_s2_3"}, {"id": "ch01_fill_8", "modI": 2, "q": "1909年，丹麦植物学家约翰森用“________”一词描述孟德尔的“遗传因子”概念。", "a": "gene", "kp": "ch01_s2_7"}, {"id": "ch01_fill_9", "modI": 3, "q": "1944年，Avery、McCarty和MacLeod证明________是转化因子，即遗传物质。", "a": "DNA", "kp": "ch01_s3_6"}, {"id": "ch01_fill_10", "modI": 3, "q": "1941年，Beadle和Tatum提出“一个基因一个________”假说，后修正为“一个基因一条________”。", "a": "酶,多肽链", "kp": "ch01_s3_3"}], "short": [{"id": "ch01_short_1", "modI": 0, "q": "简述分子生物学发展的重要里程碑。", "a": "1. 1859年达尔文《物种起源》奠定进化论基础；2. 1865年孟德尔《植物杂交实验》揭示遗传规律；3. 1910年摩尔根果蝇杂交实验将基因定位到染色体；4. 1953年沃森和克里克提出DNA双螺旋结构，标志现代分子生物学诞生；5. 2000年人类基因组工作草图宣布完成，开启基因组学时代；6. 此后CRISPR-Cas9可编程基因编辑技术建立，使精准修改基因成为可能。", "kps": "", "kp": "ch01_s0_0"}, {"id": "ch01_short_2", "modI": 0, "q": "为什么说21世纪是生命科学的世纪？", "a": "1. 当今学术论文中生命科学类占53%，在《Nature》《Science》等权威刊物中更高达56%；2. 生命科学已成为当代科学研究的主流和重心；3. 分子生物学作为生命科学的核心与前沿，带动医学、农业、环境、生物技术等领域快速发展；4. 学习分子生物学有助于理解现代生命科学的基本框架和发展方向。", "kps": "", "kp": "ch01_s0_1"}, {"id": "ch01_short_3", "modI": 1, "q": "简述细胞学说的建立及其意义。", "a": "1. 1838—1839年，德国植物学家施莱登与动物学家施旺分别研究植物和动物组织；2. 提出植物和动物都由细胞组成；3. 细胞是生物体结构和功能的基本单位；4. 该学说与进化论、孟德尔遗传学并称现代生物学三大基石；5. 奠定细胞学发展基础，为分子生物学从细胞层次深入分子层次提供前提。", "kps": "", "kp": "ch01_s1_6"}, {"id": "ch01_short_4", "modI": 2, "q": "简述摩尔根基因论的主要内容。", "a": "1. 基因确切存在；2. 基因呈线状排列在染色体上；3. 基因决定某一特定性状；4. 基因可突变和交换；5. 基因是功能单位、突变单位和重组单位，三位一体；6. 将基因从抽象概念变为染色体上的实体，奠定经典遗传学核心框架。", "kps": "", "kp": "ch01_s2_13"}, {"id": "ch01_short_5", "modI": 3, "q": "简述Avery等证明DNA是转化因子的实验思路与意义。", "a": "1. 在Griffith实验基础上，系统寻找转化因子；2. 将S型菌的各种物质分开，单独观察其转化活性，确定唯一变量；3. 结果发现只有DNA能引起转化；4. 蛋白酶、RNA酶等不能破坏转化活性，DNA酶则可使其失活；5. 从而证明DNA是转化因子，即遗传物质；6. 奠定“DNA是遗传物质”的理论基础。", "kps": "", "kp": "ch01_s3_6"}], "calc": [{"id": "ch01_calc_1", "modI": 2, "q": "论述孟德尔遗传定律的发现过程、主要内容及其对分子生物学的意义。", "a": "孟德尔以豌豆为材料开展杂交实验，1865年发表《植物杂交实验的遗传学定理》，提出分离定律和自由组合定律。分离定律：F1只表现显性性状，F2显性与隐性表型之比为3:1；性状受成对遗传因子控制，配子形成时成对因子彼此分离，分别进入不同配子。自由组合定律：两对相对性状F2出现重组类型，黄圆:黄皱:绿圆:绿皱接近9:3:3:1；不同性状的遗传因子在配子形成时独立分配、自由组合。意义：孟德尔用数学统计方法分析生物学问题，开创学科交叉先河；其工作长期被忽视，1900年三位科学家重新发现，遗传学正式诞生；为基因概念、染色体理论和分子遗传学奠定基础。", "steps": "1. 实验材料与时间；2. 分离定律要点；3. 自由组合定律要点；4. 数学统计与学科交叉；5. 重新发现与遗传学诞生；6. 对分子生物学的意义。", "kp": "ch01_s2_5"}, {"id": "ch01_calc_2", "modI": 3, "q": "论述从Griffith转化实验到Avery等证明DNA是遗传物质的逻辑链条及其科学意义。", "a": "1928年Griffith发现，将加热杀死的光滑型S型菌与粗糙型R型活菌混合注射小鼠，可导致小鼠死亡并分离出S型活菌，表明死菌中某种物质使R型菌转化为S型菌，即转化现象。转化是遗传物质在两个完全不相关的陌生个体间传递，属于水平基因交换，几乎不发生在哺乳动物中，但可发生在细菌中。1944年Avery、McCarty和MacLeod在Griffith实验基础上，将S型菌的各种物质分开，单独观察其转化活性，确定唯一变量；结果只有DNA能引起转化，蛋白酶、RNA酶等不能破坏转化活性，DNA酶则可使其失活，从而证明DNA是转化因子，即遗传物质。意义：奠定“DNA是遗传物质”的理论基础，推动分子生物学诞生。", "steps": "1. Griffith实验现象与结论；2. 转化的定义与特点；3. Avery实验设计思路；4. 关键结果；5. 结论；6. 科学意义。", "kp": "ch01_s3_6"}], "term": [{"id": "ch01_term_1", "modI": 0, "term": "Molecular Biology", "def": "现代分子生物学：以DNA双螺旋结构和中心法则为核心，从分子层次研究生命现象的科学；1953年沃森和克里克提出DNA双螺旋结构标志其诞生；是生命科学的核心与前沿，带动医学、农业、环境、生物技术等领域发展。", "kps": "", "kp": null}, {"id": "ch01_term_2", "modI": 1, "term": "Natural Selection", "def": "自然选择：达尔文在《物种起源》中提出的进化论核心机制；以“物竞天择，适者生存”解释物种起源与多样性；从根基上动摇“创世说”，使生物学摆脱神学束缚。", "kps": "", "kp": "ch01_s1_5"}, {"id": "ch01_term_3", "modI": 1, "term": "Cell Theory", "def": "细胞学说：1838—1839年由德国植物学家施莱登和动物学家施旺提出；要点包括：植物和动物都由细胞组成；细胞是生物体结构和功能的基本单位；与进化论、孟德尔遗传学并称现代生物学三大基石。", "kps": "", "kp": "ch01_s1_5"}, {"id": "ch01_term_4", "modI": 2, "term": "Mendel's Law of Segregation", "def": "孟德尔第一定律/分离定律：孟德尔以豌豆杂交实验发现；F1只表现显性性状，F2显性与隐性表型之比为3:1；性状受成对遗传因子控制；配子形成时成对因子彼此分离，分别进入不同配子；揭示遗传的基本单位与传递规律。", "kps": "", "kp": "ch01_s2_5"}, {"id": "ch01_term_5", "modI": 2, "term": "Mendel's Law of Independent Assortment", "def": "孟德尔第二定律/自由组合定律：孟德尔研究两对相对性状发现；F2除亲本类型外出现重组类型，黄圆:黄皱:绿圆:绿皱接近9:3:3:1；不同性状的遗传因子在配子形成时独立分配、自由组合；揭示非等位基因间的独立传递规律。", "kps": "", "kp": "ch01_s2_5"}, {"id": "ch01_term_6", "modI": 2, "term": "Gene", "def": "基因：1909年丹麦植物学家约翰森用“gene”描述孟德尔的“遗传因子”概念；并区分基因型与表型；使遗传学有统一核心概念；为基因与染色体关系研究奠定语言基础；标志遗传学从抽象因子向具体物质实体过渡。", "kps": "", "kp": "ch01_s2_16"}, {"id": "ch01_term_7", "modI": 2, "term": "Locus", "def": "基因座：在一个物种中，每个基因在染色体上有自己的位置；同一基因座上的不同形式称为等位基因；二倍体生物染色体通常成对存在，形成同源染色体，同源染色体上具有相对应的基因座。", "kps": "", "kp": "ch01_s2_10"}, {"id": "ch01_term_8", "modI": 2, "term": "Allele", "def": "等位基因：同一基因座上的不同形式；二倍体生物同源染色体上具有相对应的基因座；若同源染色体上等位基因相同则为纯合子，不同则为杂合子。", "kps": "", "kp": "ch01_s2_10"}, {"id": "ch01_term_9", "modI": 2, "term": "Homozygote / Heterozygote", "def": "纯合子/杂合子：二倍体生物染色体成对存在，形成同源染色体；同源染色体上等位基因相同为纯合子；同源染色体上等位基因不同为杂合子。", "kps": "", "kp": "ch01_s2_10"}, {"id": "ch01_term_10", "modI": 2, "term": "Forward Genetics", "def": "正向遗传学：早期遗传学的研究范式；通过分析突变体在世代间的传递规律，研究基因特性和染色体定位；描述基因突变和染色体变异效应；在不知基因化学本质的前提下，依靠逻辑分析的推理性科学方法。", "kps": "", "kp": "ch01_s2_16"}, {"id": "ch01_term_11", "modI": 3, "term": "Transformation", "def": "转化：遗传物质在两个完全不相关的陌生个体间传递，属于水平基因交换；几乎不发生在哺乳动物中，但可发生在细菌中；1928年Griffith肺炎链球菌实验首次揭示；1944年Avery等证明DNA是转化因子。", "kps": "", "kp": "ch01_s3_1"}, {"id": "ch01_term_12", "modI": 3, "term": "One Gene-One Enzyme Hypothesis", "def": "一个基因一个酶假说：1941年George Beadle和Edward Tatum提出；认为基因的生化作用本质是控制酶的合成；获1958年诺贝尔生理学或医学奖；后来修正为“一个基因一条多肽链”；将基因与蛋白质功能直接联系起来。", "kps": "", "kp": "ch01_s3_1"}], "preview": {"main": "本章以时间轴为线索，梳理从达尔文进化论、孟德尔遗传学到DNA双螺旋的分子生物学诞生历程，重点阐述遗传物质本质的探索与经典遗传学向分子生物学的过渡。", "questions": ["为什么说1953年DNA双螺旋结构的提出标志着现代分子生物学的诞生？", "孟德尔的遗传定律为何被忽视长达35年，又如何在1900年被重新发现？", "摩尔根的果蝇实验如何证明基因位于染色体上，并推动遗传的染色体理论？", "Avery等人的肺炎链球菌转化实验和Hershey-Chase噬菌体实验如何证明DNA是遗传物质？", "细胞学说、进化论和孟德尔遗传学为何被称为现代生物学的三大基石？", "从早期遗传学到分子生物学，研究范式发生了怎样的转变？"]}, "appcards": [{"front": "为什么说1953年DNA双螺旋结构的提出是现代分子生物学诞生的标志？请结合分子生物学发展里程碑比较说明。", "back": "①此前研究（达尔文进化论、孟德尔遗传规律、摩尔根基因定位）主要停留在宏观遗传现象和染色体水平，未阐明基因的分子本质；②1953年沃森和克里克提出DNA双螺旋结构，首次从分子水平揭示遗传信息的储存和传递机制；③此后中心法则、DNA复制、转录翻译等分子机制研究有了结构基础；④因此它标志着生物学研究从染色体/基因水平进入分子水平，现代分子生物学正式诞生。", "points": "此前研究停留在宏观/染色体水平；DNA双螺旋揭示分子本质；为后续分子机制提供结构基础；标志进入分子水平/现代分子生物学诞生", "mod": 0, "modName": "模块一：分子生物学与21世纪生命科学", "level": "掌握", "src": "生成"}, {"front": "从1859年到2000年，分子生物学的发展体现了怎样的趋势？请举例说明。", "back": "①研究层次不断深入：从达尔文进化论（个体/物种水平）→孟德尔遗传规律（性状/遗传因子）→摩尔根果蝇实验（染色体水平）→DNA双螺旋（分子水平）→人类基因组草图（全基因组水平）；②技术手段不断突破：从杂交实验、果蝇遗传分析到X射线衍射、DNA测序、CRISPR基因编辑；③应用导向增强：从认识生命规律到精准修改基因、基因组学与医学农业应用。", "points": "研究层次由宏观到分子/基因组；技术手段不断突破；应用导向增强；需举出至少两个里程碑例子", "mod": 0, "modName": "模块一：分子生物学与21世纪生命科学", "level": "掌握", "src": "生成"}, {"front": "为什么说21世纪是生命科学的世纪？请从学科地位和对其他领域带动作用两方面说明。", "back": "①学科地位：当今学术论文中生命科学类占53%，在《Nature》《Science》等权威刊物中高达56%，说明生命科学已成为当代科学研究的主流和重心；②带动作用：分子生物学作为生命科学核心与前沿，带动医学、农业、环境、生物技术等领域快速发展；③因此21世纪被称为生命科学的世纪，学习分子生物学有助于理解现代生命科学基本框架和发展方向。", "points": "论文占比53%/权威刊物56%；生命科学成为主流和重心；分子生物学是核心前沿；带动医学农业环境生物技术；有助于理解现代生命科学框架", "mod": 0, "modName": "模块一：分子生物学与21世纪生命科学", "level": "掌握", "src": "生成"}, {"front": "社会各界高度关注生命科学体现在哪些方面？请举例说明这种关注对分子生物学发展的意义。", "back": "①政府层面：各国政府高度关注前沿学科；②科学家层面：联合抢占制高点；③企业层面：有远见的企业家投入巨资发展生物技术；④媒体层面：频繁聚焦生物技术成果；⑤民众层面：关心转基因食品与环境安全；⑥高校层面：将分子生物学列为学位课程。意义：多方关注推动事件、决策和观念更新，为分子生物学研究提供政策、资金、人才和舆论支持，标志生命科学世纪全面到来。", "points": "政府/科学家/企业/媒体/民众/高校六层面；举例转基因食品、企业投资、高校课程等；意义：推动事件决策观念更新；提供政策资金人才舆论支持；标志生命科学世纪到来", "mod": 0, "modName": "模块一：分子生物学与21世纪生命科学", "level": "掌握", "src": "生成"}, {"front": "比较达尔文进化论与细胞学说在“动摇旧观念、奠定现代生物学基础”方面的异同。", "back": "相同点：①都产生于19世纪，属于现代生命科学的重要基石；②都以自然原因解释生命现象，推动生物学摆脱神学或旧观念束缚；③都为分子生物学提供历史与思想背景。不同点：①进化论以自然选择解释物种起源与多样性，冲击“创世说”；②细胞学说以细胞为生物体结构和功能的基本单位，奠定细胞学基础；③进化论侧重物种层次与历史演化，细胞学说侧重个体结构与功能层次。", "points": "相同点：19世纪、现代生物学基石、自然原因解释、摆脱神学束缚、为分子生物学提供背景；不同点：进化论—物种起源与多样性、自然选择、冲击创世说；细胞学说—细胞为基本单位、结构功能层次、奠定细胞学基础。", "mod": 1, "modName": "模块二：发展历程(一)——进化论与细胞学说", "level": "掌握", "src": "生成"}, {"front": "为什么说达尔文进化论的提出使生物学“走上以自然原因解释生命现象的道路”？请从原因机制角度说明。", "back": "①达尔文通过贝格尔号环球考察积累大量生物与地质证据；②提出以自然选择为核心的进化论，用“物竞天择，适者生存”解释物种起源与多样性；③该理论从根基上动摇了上帝创造万物的“创世说”；④使生物学不再依赖神学解释，而用自然选择等自然原因说明生命现象；⑤因此生物学逐渐成为以实证和自然机制为基础的科学。", "points": "环球考察与证据积累；自然选择核心；物竞天择、适者生存；解释物种起源与多样性；动摇创世说；摆脱神学束缚；以自然原因解释生命现象。", "mod": 1, "modName": "模块二：发展历程(一)——进化论与细胞学说", "level": "掌握", "src": "生成"}, {"front": "列文虎克与胡克在细胞学说建立过程中分别作出了什么贡献？这体现了技术革新对生物学发展的什么意义？", "back": "①列文虎克自制单式显微镜，首次观察记录到细菌、原生动物、精子等微小生物，为细胞学说建立提供观察工具与事实基础；②胡克改进复合显微镜，1665年出版《显微图谱》，观察软木薄片时首次将小室命名为“cell”，使“cell”进入生物学；③二者都说明显微观察技术革新推动人类从显微层次认识生命结构；④技术革新为细胞学说的建立提供工具和事实基础，也推动生物学发展。", "points": "列文虎克：自制单式显微镜、首次观察记录微小生物、提供工具与事实基础；胡克：改进复合显微镜、《显微图谱》、命名cell、核心概念；技术革新意义：推动显微层次认识生命、为细胞学说提供前提、促进生物学发展。", "mod": 1, "modName": "模块二：发展历程(一)——进化论与细胞学说", "level": "掌握", "src": "生成"}, {"front": "细胞学说的主要内容是什么？它为什么能与进化论、孟德尔遗传学并称现代生物学三大基石？请举例说明其意义。", "back": "①1838—1839年，施莱登与施旺分别研究植物和动物组织，提出：植物和动物都由细胞组成；细胞是生物体结构和功能的基本单位。②它奠定了细胞学发展的基础，使人们从细胞层次认识生命结构。③它与进化论、孟德尔遗传学共同构成现代生命科学的重要基石。④举例：胡克观察软木薄片命名“cell”，列文虎克观察微小生物，为细胞学说提供事实基础；细胞学说又为分子生物学从细胞层次深入分子层次提供前提。", "points": "施莱登与施旺；1838—1839；植物和动物都由细胞组成；细胞是结构和功能基本单位；奠定细胞学基础；与进化论、孟德尔遗传学并称三大基石；为分子生物学提供前提；举例胡克或列文虎克。", "mod": 1, "modName": "模块二：发展历程(一)——进化论与细胞学说", "level": "掌握", "src": "生成"}, {"front": "孟德尔的分离定律与自由组合定律分别揭示了什么遗传规律？二者在实验对象和结论上有何区别与联系？", "back": "分离定律：以一对相对性状为对象，F1只表现显性，F2显隐比3:1；成对遗传因子在配子形成时彼此分离，分别进入不同配子。自由组合定律：以两对相对性状为对象，F2出现重组类型，黄圆:黄皱:绿圆:绿皱≈9:3:3:1；不同性状的遗传因子在配子形成时独立分配、自由组合。联系：分离定律是自由组合定律的基础，自由组合定律揭示非等位基因间的独立传递，为遗传变异和重组提供理论基础。", "points": "分离定律对象与3:1；成对因子分离；自由组合定律对象与9:3:3:1；非等位基因独立分配；二者联系", "mod": 2, "modName": "模块三：发展历程(二)——遗传学与染色体理论", "level": "掌握", "src": "生成"}, {"front": "为什么说孟德尔选用豌豆作为实验材料是其成功的重要原因？请从性状、授粉方式和统计方法三方面说明。", "back": "性状方面：豌豆有7对易于区分的相对性状，且具明显显隐性关系，便于追踪。授粉方式：豌豆自花授粉、易于人工杂交，可控制亲本交配。统计方法：孟德尔用数学统计方法分析生物学问题，开创学科交叉先河，从大量后代中归纳出规律。", "points": "7对相对性状；明显显隐性；自花授粉且易人工杂交；数学统计；学科交叉", "mod": 2, "modName": "模块三：发展历程(二)——遗传学与染色体理论", "level": "掌握", "src": "生成"}, {"front": "摩尔根的果蝇实验如何证明基因位于染色体上？遗传连锁图又怎样使基因定位成为可能？", "back": "果蝇实验：1910年摩尔根通过果蝇杂交实验，将基因与染色体联系起来，证明基因位于染色体上，并揭示伴性遗传等现象，为遗传的染色体理论提供直接证据。连锁图：摩尔根绘制第一个成功的遗传图谱，显示果蝇第二条染色体上等位基因的相对位置；基因间距离以摩厘表示，等于染色体交换事件的百分比；重组频率越大距离越远，越小距离越近，从而使基因定位成为可能。", "points": "果蝇杂交实验；基因位于染色体；伴性遗传；第一个遗传图谱；摩厘与交换百分比；重组频率与距离关系", "mod": 2, "modName": "模块三：发展历程(二)——遗传学与染色体理论", "level": "掌握", "src": "生成"}, {"front": "孟德尔、摩尔根和麦克林托克三位科学家在遗传学发展中的主要贡献分别是什么？他们的工作如何体现从抽象规律到物质实体再到物理证据的递进？", "back": "孟德尔：以豌豆杂交实验提出分离定律和自由组合定律，用数学统计研究生物学，被誉为遗传学之父，使遗传因子成为抽象规律的核心。摩尔根：通过果蝇实验证明基因位于染色体上，提出基因论，认为基因呈线状排列在染色体上，是功能、突变和重组单位三位一体，并绘制遗传连锁图，使基因成为染色体上的实体。麦克林托克：1931年与克赖顿在玉米中直接证明重组现象，后发现转座子，获1983年诺贝尔奖，为遗传重组提供物理证据。递进：孟德尔抽象规律→摩尔根染色体实体→麦克林托克物理证据。", "points": "孟德尔两定律与数学统计；摩尔根果蝇实验、基因论、连锁图；麦克林托克玉米重组证据、转座子；抽象规律到实体到物理证据的递进", "mod": 2, "modName": "模块三：发展历程(二)——遗传学与染色体理论", "level": "掌握", "src": "生成"}, {"front": "为什么说Avery等人的工作动摇了“蛋白质是基因”的理念？请从实验设计、结果和当时背景三方面说明。", "back": "①实验设计：在Griffith转化实验基础上，将S型菌的各种物质分开，单独观察其转化活性，确定唯一变量。②结果：只有DNA能引起转化，蛋白酶、RNA酶不能破坏转化活性，DNA酶可使其失活，证明DNA是转化因子。③当时背景：科学家对核酸了解甚少，普遍认为蛋白质可能是遗传专一性的决定分子。因此该发现第一个动摇了“蛋白质是基因”的理念，奠定了“DNA是遗传物质”的理论基础。", "points": "实验设计（分离各物质、单一变量）；结果（DNA引起转化、DNA酶失活、蛋白酶/RNA酶无效）；背景（蛋白质被普遍认为是遗传决定分子）；结论（动摇蛋白质是基因、奠定DNA是遗传物质基础）", "mod": 3, "modName": "模块四：发展历程(三)——生物化学与DNA的发现", "level": "掌握", "src": "生成"}, {"front": "Hershey-Chase实验为什么能证明DNA而不是蛋白质是遗传物质？请说明其原理、关键结果和结论。", "back": "①原理：噬菌体T2由蛋白质外壳和DNA核心组成，感染大肠杆菌时只有DNA进入宿主细胞，蛋白质外壳留在外面。②标记与追踪：用32P标记DNA，35S标记蛋白质；搅拌使外壳脱落，离心后细菌沉淀、外壳在上清。③结果：32P标记的DNA出现在沉淀中并传递给子代噬菌体，35S标记的蛋白质出现在上清中，子代噬菌体含32P不含35S。④结论：DNA进入宿主并传递给子代，蛋白质未进入，直接证明DNA是遗传物质，蛋白质不是。", "points": "噬菌体结构（蛋白质外壳+DNA核心）；感染特点（只有DNA进入）；同位素标记（32P标DNA、35S标蛋白质）；搅拌离心结果（32P在沉淀、35S在上清）；子代结果（含32P不含35S）；结论（DNA是遗传物质，蛋白质不是）", "mod": 3, "modName": "模块四：发展历程(三)——生物化学与DNA的发现", "level": "掌握", "src": "生成"}, {"front": "从Griffith到Hershey-Chase，DNA作为遗传物质的证明经历了怎样的发展历程？这一历程有什么科学意义？", "back": "①历程：1928年Griffith发现肺炎链球菌转化现象，首次揭示遗传信息可在细菌间传递；1944年Avery等证明DNA是转化因子；1952年Hershey-Chase用32P和35S标记噬菌体证明DNA是主要遗传物质；1953年Watson和Crick提出DNA双螺旋结构模型。②意义：确立了DNA是主要遗传物质，将遗传学与生物化学统一起来，催生了分子生物学；展示了科学假说不断被验证和修正的过程；为基因克隆、基因工程等现代生物技术奠定了基础。", "points": "Griffith转化现象（1928）；Avery证明DNA是转化因子（1944）；Hershey-Chase证明DNA是主要遗传物质（1952）；Watson-Crick双螺旋（1953）；意义（确立DNA地位、统一遗传学与生物化学、催生分子生物学、奠定生物技术基础、体现假说验证修正）", "mod": 3, "modName": "模块四：发展历程(三)——生物化学与DNA的发现", "level": "掌握", "src": "生成"}, {"front": "“一个基因一个酶”假说后来为什么被修正为“一个基因一条多肽链”？请举例说明这一假说的意义。", "back": "①原因：并非所有基因产物都是酶，有些基因编码结构蛋白或其他非酶多肽；一个基因对应一条多肽链更准确。②先导思想：Garrod早在1911年提出先天性代谢缺陷与酶缺陷有关。③提出：1941年Beadle和Tatum提出“一个基因一个酶”，获1958年诺贝尔生理学或医学奖。④意义：将基因与蛋白质功能直接联系起来，是分子生物学发展的重要里程碑。⑤举例：先天性代谢缺陷病可因某种酶缺陷导致代谢异常，说明基因通过控制酶（多肽链）合成影响生化反应。", "points": "修正原因（基因产物不都是酶、一个基因对应一条多肽链更准确）；Garrod先导思想；Beadle和Tatum提出及诺奖；意义（联系基因与蛋白质功能、分子生物学里程碑）；举例（先天性代谢缺陷与酶缺陷）", "mod": 3, "modName": "模块四：发展历程(三)——生物化学与DNA的发现", "level": "掌握", "src": "生成"}, {"front": "为什么说Chargaff规则为DNA双螺旋模型中A-T、G-C的互补配对提供了关键化学线索？请结合碱基组成规律说明其推理作用。", "back": "Chargaff发现不同生物DNA中A≈T、G≈C，即A=T、G=C，由此推出A+G=T+C（嘌呤总数等于嘧啶总数）；但A+T与G+C的比值因物种而异。这说明DNA碱基组成不是随机的，而是存在固定的配对关系：一个嘌呤对应一个嘧啶。该定量规律直接提示A与T、G与C之间可能存在互补配对，为Watson和Crick建立双螺旋模型中碱基位于内侧、通过氢键互补配对的机制提供了重要化学依据。", "points": "A=T、G=C；A+G=T+C；嘌呤数=嘧啶数；A+T/G+C因物种而异；提示嘌呤-嘧啶互补配对；支持A-T、G-C模型。", "mod": 4, "modName": "模块五：发展历程(四)——DNA双螺旋与中心法则", "level": "掌握", "src": "生成"}, {"front": "DNA双螺旋结构的提出为什么被视为分子生物学的诞生标志？请从信息储存、复制和传递三个角度说明其意义。", "back": "1953年Watson和Crick综合X射线衍射数据、Chargaff规则和化学键理论提出DNA双螺旋模型：两条反向平行多核苷酸链围绕共同轴盘旋，碱基位于内侧并互补配对，磷酸-脱氧核糖骨架位于外侧。其意义在于：①储存：碱基序列可编码遗传信息；②复制：互补配对使DNA可半保留复制，保证遗传信息稳定传递；③传递：结构解释了遗传信息如何从亲代DNA传到子代，并为后续转录、翻译研究奠定结构基础。因此它标志着分子生物学的诞生。", "points": "1953年Watson和Crick；反向平行双链；碱基内侧互补配对；骨架外侧；解释遗传信息储存；解释复制；解释传递；标志分子生物学诞生。", "mod": 4, "modName": "模块五：发展历程(四)——DNA双螺旋与中心法则", "level": "掌握", "src": "生成"}, {"front": "Rosalind Franklin的“51号照片”对DNA双螺旋发现有何关键贡献？为什么完整讲述这段历史必须包括她的贡献？", "back": "Franklin利用X射线晶体衍射研究DNA纤维，获得“51号照片”，清晰显示DNA呈螺旋状，并提示由两条或三条多核苷酸链组成，为Watson和Crick确定DNA三维结构提供了决定性实验证据。她1958年去世，未能分享1962年诺贝尔奖，早期叙述中也常被淡化。完整讲述发现史必须包括Franklin，是因为：①尊重历史事实；②承认X射线衍射数据对模型建立的关键作用；③反思科学评价中的公平与性别问题。", "points": "X射线晶体衍射；51号照片；显示螺旋状；提示多核苷酸链；为双螺旋提供关键证据；1958年去世未获诺奖；早期贡献被淡化；尊重历史；关注公平与性别问题。", "mod": 4, "modName": "模块五：发展历程(四)——DNA双螺旋与中心法则", "level": "掌握", "src": "生成"}, {"front": "中心法则和序列假说的核心内容是什么？它们如何奠定分子生物学信息流向的基本框架？", "back": "1957年Crick系统论述中心法则和序列假说。序列假说认为：核酸携带的遗传信息由碱基序列决定；对蛋白质编码基因而言，核酸碱基序列决定蛋白质氨基酸序列。中心法则指出：序列信息一旦从核酸传递到蛋白质，就不能再以蛋白质为模板传回核酸。即信息流基本方向为DNA→RNA→蛋白质。该原则奠定了分子生物学信息流向框架，后续补充了RNA逆转录和RNA复制等例外。", "points": "1957年Crick；序列假说；碱基序列决定氨基酸序列；中心法则；信息从核酸到蛋白质；不能从蛋白质传回核酸；DNA→RNA→蛋白质；后续补充逆转录、RNA复制。", "mod": 4, "modName": "模块五：发展历程(四)——DNA双螺旋与中心法则", "level": "掌握", "src": "生成"}, {"front": "比较还原论与整体论两种研究策略，并说明人类基因组计划（HGP）为何被视为研究策略转变的标志。", "back": "还原论主张“化繁为简”，通过分解复杂生命现象来研究其组成部分，20世纪生物学主要采用此策略；整体论强调从全局和系统层面理解生命，关注各组分间的相互联系与整体行为。HGP于1990年启动，目标是测定人类全基因组序列，它推动了大科学和组学时代，使研究从单个基因转向全基因组、全转录组等整体分析，因此成为从还原论向整体论转变的标志性事件。", "points": "还原论定义（化繁为简、分解研究）；整体论定义（全局、系统层面）；HGP启动时间1990年；HGP推动组学/大科学时代；研究从单个基因转向全基因组等整体分析", "mod": 5, "modName": "模块六：现代分子生物学的研究内容与发展", "level": "掌握", "src": "生成"}, {"front": "为什么说从经典模式生物转向噬菌体等简单模式生物是分子生物学发展的重要转折？请举例说明其意义。", "back": "20世纪中期，研究对象从果蝇、豌豆等经典材料转向微生物、噬菌体及其他简单模式生物。噬菌体群的研究催生了顺反子、“一基因一酶”假说、操纵子等新理论和新概念，使生物学开始腾飞。Delbrück、Hershey和Luria因噬菌体研究获1969年诺贝尔奖。这一转变体现了简单模式生物在揭示生命基本规律中的巨大优势，如繁殖快、基因组小、易于遗传操作，从而加速了分子机制的发现。", "points": "研究对象转变（经典模式生物→微生物/噬菌体）；噬菌体群催生新理论（顺反子、一基因一酶、操纵子）；1969年诺贝尔奖（Delbrück、Hershey、Luria）；简单模式生物优势（繁殖快、基因组小、易操作）；加速分子机制发现", "mod": 5, "modName": "模块六：现代分子生物学的研究内容与发展", "level": "掌握", "src": "生成"}, {"front": "现代分子生物学的六大研究内容是什么？它们之间有何内在联系？", "back": "六大研究内容：①基因功能研究（功能基因如何发挥功能）；②基因表达调控研究（蛋白质发挥功能的机制、蛋白质结构与合成时序同核酸的关系）；③信号转导研究（已发展为细胞生物学分支）；④DNA重组技术（催生基因工程分支）；⑤生物大分子结构与功能研究（形成结构分子生物学）；⑥基因组与功能基因组的宏观分析（推动生物信息学兴起）。这些方向相互交叉，构成现代分子生物学的核心框架，从单个基因到全局组学、从结构到功能、从基础到应用形成完整体系。", "points": "列出六大研究内容（基因功能、表达调控、信号转导、DNA重组、结构分子生物学、基因组/功能基因组）；指出相互交叉；构成核心框架；从单个基因到全局组学；从基础到应用", "mod": 5, "modName": "模块六：现代分子生物学的研究内容与发展", "level": "掌握", "src": "生成"}, {"front": "Maddox对分子生物学研究现状的批评是什么？这一反思对分子生物学发展有何意义？", "back": "Maddox于1992年在《自然》发表《Is molecular biology yet a science?》，批评大批分子生物学家发表的论文不涉及完整动植物，也很少讨论生理学，实验数据可能主要由“gels”（凝胶电泳图）构成。这指出研究可能过度聚焦于还原性、技术性数据，而忽视整体生物体和生理功能。其意义在于提醒分子生物学需与生理学、细胞生物学和整体生物学结合，才能全面理解生命现象；同时促使研究者思考如何从描述性研究走向机制整合与理论统一，推动学科成熟。", "points": "Maddox 1992年Nature文章；批评内容（不涉及完整动植物、少讨论生理学、数据主要为gels）；指出过度聚焦还原性/技术性数据；意义（需与生理学、细胞生物学、整体生物学结合）；促使从描述性研究走向机制整合与理论统一", "mod": 5, "modName": "模块六：现代分子生物学的研究内容与发展", "level": "掌握", "src": "生成"}]};